quests[70047] = { id = 70047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisige Gefängnisse" }
quests[70048] = { id = 70048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Urbedrohung", description = "Raszageth hat keine Zeit verschwendet, ihre Primalistenstreitkräfte auszubauen.\n\nDie Kirin Tor haben massive Stürme entdeckt, die an Schlüsselpunkten in Kalimdor und den Östlichen Königreichen freigesetzt werden.\n\nDie Primalisten entfesseln die Elemente, um ihre Macht zu stärken. Es scheint, als hätten sie nicht nur auf den Dracheninseln, sondern auch in den Ländern der Allianz und der Horde vor, Chaos zu stiften.\n\nSucht den Feind auf und studiert seine Methoden. Wir müssen ihn aufhalten, bevor es zu spät ist.", sourceObjective = "Sammelt 10 Partikel urtümlicher Energie von Gegnern an Orten aktiver Urstürme in Kalimdor und den Östlichen Königreichen.", progress = "Ich fürchte, das ist erst der Anfang.", completion = "Zum Glück konntet Ihr ihren Angriff vereiteln, zumindest für den Moment.\n\n<Khadgar untersucht die Partikel, die Ihr ihm gebracht habt.>\n\nHmm, Urelementarenergie. Ich werde das genauer studieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[70049] = { id = 70049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stürme beruhigen", description = "Diese Primalisten sind erbarmungslos und entfesseln elementare Verwüstung in den Östlichen Königreichen und Kalimdor.\n\nIhr müsst genau so viel Entschlossenheit zeigen, {name}. Das ist der einzige Weg, sie aufzuhalten.\n\nFindet heraus, wo sie als Nächstes eindringen, entfernt die Gegner im Gebiet des Ursturms, bevor es zu spät ist, und macht ihre Pläne zunichte.\n\nWir müssen Azeroth beschützen!", sourceObjective = "Sammelt 10 Partikel urtümlicher Energie von Gegnern an Orten aktiver Urstürme in Kalimdor und den Östlichen Königreichen.", progress = "Unsere Arbeit geht weiter.", completion = "Gut gemacht. Hoffen wir, dass uns das bis zu ihrem nächsten Eindringen etwas Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[70050] = { id = 70050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmjagd", description = "Die hübschen Leutchen schicken Euch also auf ein kleines Abenteuer, wie?\n\nKeine Sorge. Bis jemand diese Elementarstürme in den Griff bekommt, können wir eh nicht losschippern.\n\nSprecht mit Sturmjäger William. Er ist in der Expedition für die Untersuchung der Stürme verantwortlich und kann Euch sicher mit der nötigen Ausrüstung versorgen.\n\nIch koordiniere von hier den Rest der Vorbereitungen, während Ihr da draußen Spaß habt.\n\nDafür seid Ihr mir aber was schuldig, klar?", sourceObjective = "Sprecht mit Sturmjäger William am Hafen von Sturmwind.", completion = "Wenn Ihr Kurs auf diese Stürme nehmt, braucht Ihr alle Hilfe, die Ihr bekommen könnt.\n\nZum Glück für Euch sammle ich schon seit Jahren Ausrüstung für Sturmjäger.\n\nSchaut Euch um und sucht Euch was Passendes aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[70051] = { id = 70051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klippenrundstrecke", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70052] = { id = 70052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klippenrundstrecke - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70055] = { id = 70055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der Stürme", description = "<Jemand mit großem magischen Wissen würde so etwas sicherlich gerne studieren wollen.>", sourceObjective = "Bringt das Siegel der Stürme zu Sturmjäger William in Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "Was die Magie angeht, übersteigt das mein Wissen leider deutlich.\n\nAber ich werde es zu Khadgar bringen. Gebietet Ihr weiter der Bedrohung durch die Primalisten Einhalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70057] = { id = 70057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Tarasek" }
quests[70058] = { id = 70058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund zu reparieren", description = "Glücksente wurde verletzt, während wir rumgeflogen sind... Es ging ihr so gut und dann bin ich... Ich bin gegen einen Baum gestoßen!\n\n<Lillistrasza deutet traurig auf die beschädigte Stoffente auf ihrem Kopf.>\n\nIhre Füllung fällt raus! Ihre Federn sind ganz verbogen! Eines ihrer Augen ist verschwunden! Neiiiiin!\n\nIhr könnt doch helfen, Glücksente zu reparieren, oder?", sourceObjective = "Sammelt 5 weiche Rubinfedern, 3 Stofffetzen und 1 Glasperle in der Nähe des Rubinlebensschreins, um Glücksente zu reparieren.", progress = "Ja? Ich helfe, wo ich kann!", completion = "Ja, ja! Diese Materialien sollten reichen, um deine Glücksente zu reparieren, Kleine.\n\n<Mahra lächelt Euch an.>\n\nHabt Dank, dass Ihr mir von dieser wichtigen Angelegenheit berichtet habt, {name}. Es sollte nicht lange dauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70059] = { id = 70059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akademieaufstieg", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70060] = { id = 70060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akademieaufstieg - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70061] = { id = 70061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übungsflügel", sourceObjective = "Weist einen Welpen dazu an, 12 aufgebrachte Unkrautlinge, 6 aufdringliche Welpenstecher und 1 unerbittliche Windstöße zu erledigen.", progress = "Manche Welpen brauchen mehr Ermutigung als andere. Natürlich lieben wir sie alle.", completion = "Es tut gut, zu sehen, mit welcher Freude und Freiheit in ihren Herzen unsere Jungen herumfliegen. Habt Dank, dass Ihr ihnen dazu verholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70062] = { id = 70062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einige nennen mich Käferfänger", description = "Ah, <junger/junge:r> {race}, ich könnte Eure Hilfe brauchen. Ich habe hier Generationen von Leben großgezogen.\n\nAm liebsten habe ich die Entchen. Aber mein Körper ist alt und schwach geworden... doch das hält den Kreislauf nicht auf.\n\nIch brauche Euch, um Nahrung für meine Brut zu fangen.", sourceObjective = "Sammelt 6 Flugbrutkäferstücke.", progress = "Für alle Kreaturen gibt es einen Anfang und ein Ende. Dabei spielt es keine Rolle, wie weit auseinander sie liegen.", completion = "Oh... schon zurück? Wie die Zeit verfliegt.\n\nUnd Ihr habt sogar die guten Stücke!\n\nKnallentchen und Pilot werden das Chitin lieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[70064] = { id = 70064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Imbu!" }
quests[70066] = { id = 70066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückeroberung der Festung" }
quests[70067] = { id = 70067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft an die Nokhud" }
quests[70068] = { id = 70068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kobaltkatastrophe" }
quests[70069] = { id = 70069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andere nennen mich Entenhüter", description = "Meine Tage werden kürzer... doch meine Pflichten sind noch nicht erfüllt.\n\nDie Brut sollte am Fluss sein. Ich habe sie in der Hoffnung dort gelassen, dass es sie selbstständiger macht. Bald werden sie sich selbst verteidigen müssen.\n\nHeute verlassen sie sich noch auf Euch. Bringt ihnen bitte das Essen, das Ihr gefangen habt, und die Entchen dann zu mir. Passt auf Pilot auf, sie springt ständig von irgendetwas runter.", sourceObjective = "Füttert 4 Entchen und kehrt zu Gracus zurück.", completion = "Meine wunderschönen Entchen! Ihr seht so stark aus!\n\nPilot, komm. Die Zeit zum Spielen ist vorbei.\n\n<Pilot weicht nicht von Eurer Seite und versucht, sich hinter Euren Beinen zu verstecken. Bis Gracus sie aufhebt.>\n\nSie hat anscheinend Gefallen an Euch gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[70070] = { id = 70070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aber... ich bin der Held der Enten", description = "Einen Moment... Irgendetwas ist doch...\n\n<Gracus sieht sich um.>\n\nKnallentchen! Der Racker muss wieder flussabwärts sein! Egal, wie oft ich es ihm sage, ständig versucht er, mit den Flunkern zu spielen!\n\nIhr müsst für mich nach ihm sehen. Hoffentlich wurde er nicht wieder verschluckt.", sourceObjective = "Findet Knallentchen und stellt sicher, dass er zu Gracus zurückkehrt.", progress = "Ich liebe alle meine Kinder, aber diese Entchen sind die letzten, die ich aufziehen werde.\n\nKnallentchen ist ein ganz schöner Schelm. Trotzdem liebe ich ihn am meisten. Er führte mich direkt zu den jüngeren, als ich ihn als Ersten fand.", completion = "Er wurde wieder verschluckt...\n\nKnallentchen hat noch viel zu lernen.\n\nPilot, auf der anderen Seite, hat Euch bereits ins Herz geschlossen. Sie ist die Klügste der Brut und am ehesten bereit, das Nest zu verlassen.\n\nIch danke Euch für alles, was Ihr getan habt! Kümmert Euch um meine süßen Entchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70071] = { id = 70071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Sammeln der Magie" }
