quests[70112] = { id = 70112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furbolgbedrohung" }
quests[70122] = { id = 70122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscher in Not", sourceObjective = "Rettet 3 Mitglieder der Drachenschuppenexpedition an der Wilden Küste.", completion = "Die Drachen sind nicht hier, um uns zu treffen, wie Furorion versprochen hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[70123] = { id = 70123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urgeziefer", description = "<Azurathel wirft einen misstrauischen Blick auf die Protodrachen, die hinter ihm auf dem Gebirgskamm lauern.>\n\nIch könnte schwören, dass diese Protodrachen jedes Mal, wenn ich ihnen den Rücken zuwende, näher an das Lager herankommen...\n\nDas sind nicht die Drachen, die Furorion uns hier vorstellen wollte.\n\nDie Protodrachen sind skrupellose Raubtiere, mit denen man nicht verhandeln kann. Wir müssen ebenso skrupellos sein.\n\nDezimiert sie, um sie unter Kontrolle zu halten, oder diese Expedition ist zu Ende, bevor sie begonnen hat.", sourceObjective = "Tötet 8 Urprotodrachen an der Wilden Küste.", completion = "Das sollte sie eine Weile lang davon abhalten, die Expeditionslager anzugreifen.\n\nAuf den Dracheninseln gilt \"Fressen oder gefressen werden\", {name}. Das solltet Ihr Euch merken.", sourceObjectiveStatus = "unverified-source-field" }
quests[70124] = { id = 70124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übungsmaterialien", description = "Die Protodrachen hier unterscheiden sich von allem, was ich bisher gesehen habe.\n\nIhre Schuppen scheinen von Natur aus feuerfest zu sein, stärker als Stahl, und sie büßen dabei nicht an Flexibilität ein. Unglaublich.\n\nDie Handwerker wollen unbedingt einige davon in die Hände bekommen, um damit zu arbeiten.\n\nBeginnt mit den Welpen. Ihre kleineren Schuppen sollten biegsamer sein und uns dabei helfen, unsere Techniken zu verbessern.", sourceObjective = "Sammelt 12 Urprotowelpenschuppen.", progress = "Habt Ihr die Schuppen?", completion = "<Thaelin untersucht die Schuppen sorgfältig.>\n\nBrillant! Unsere Handwerker werden sie gut brauchen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[70125] = { id = 70125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Furorion?", description = "Hm, ich frage mich, wo Furorion bleibt.\n\nEr sagte, er würde hier auf uns warten, zusammen mit einem Botschafter von Alexstrasza der Lebensbinderin, Königin der Drachen.\n\nEs sieht einem Drachen nicht ähnlich, ein Versprechen nicht zu halten.\n\nNun denn! Wenigstens ist diese eifrige, kleine Drakonide hier, um uns zu empfangen. Fragt sie doch einmal, wann die anderen ankommen.", sourceObjective = "Fragt Sendrax, wann die Drachen ankommen sollten.", progress = "Willkommen auf den Dracheninseln, mein Freund!\n\n...Ich glaube, das habe ich schon mal gesagt. Egal! Ich bin einfach froh, dass Ihr hier seid!", completion = "Ich weiß es nicht! Wie gesagt, das ist mein erster Auftrag... Lasst mich kurz nachdenken, was zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[70126] = { id = 70126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schliff", sourceObjective = "Überzeugt Miguels Kunden, sich bei künftigen Handwerksaufträgen an ihn zu wenden.", progress = "Das ist das Geheimnis, {name}. Es sind manchmal die kleinen Nettigkeiten, auf die es in einer Beziehung ankommt.", completion = "Nehmt diese Fertigungsreagenzien und verwendet sie, um Eure Handwerksfertigkeit zu verbessern, wenn Ihr mal wirklich etwas von hoher Qualität benötigt.\n\nSeid nett und höflich zu Euren Kunden, dann werden sie Euch mit weiteren Aufträgen beehren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70129] = { id = 70129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehenmatsch der Schreckliche", description = "Ihr habt recht, ich bin nicht stark genug, um es mit diesem Yeti aufzunehmen... zumindest nicht alleine!\n\nDoch Ihr seid hier!\n\nDer Bau des bösen Yetis, Zehenmatsch des Schrecklichen, liegt vor uns. Diese Höhle ist... groß. Aber nicht gruselig! Okay, vielleicht ein bisschen gruselig.\n\nKönntet Ihr reingehen und ihn schon mal etwas mürbe machen? Ich... Ich bin direkt hinter Euch!", sourceObjective = "Helft Rowie, Zehenmatsch den Schrecklichen zu erlegen.", completion = "Liebe Güte, was habt Ihr ihm gesagt? Ich habe Rowie noch nie so ermutigt gesehen!\n\nHabt Dank, dass Ihr ihn heimgebracht habt. Ich werde mein Bestes geben, mich in Kaqiatas Haus um ihn zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70132] = { id = 70132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Weilchen bleiben", description = "<Der alte Zwerg reagiert nicht auf Euch, als Ihr Euch nähert, sondern blickt mit gerunzelter Stirn über die Landschaft. Es ist ein wohltuender Ausblick, vielleicht solltet Ihr ebenfalls eine Pause einlegen und die Landschaft betrachten.>", sourceObjective = "Setzt Euch eine Weile. Betrachtet die Landschaft.", progress = "<Der Zwerg lässt seinen Blick in die Ferne schweifen. Ihr bemerkt, dass ihm Tränen in die Augen steigen.>", completion = "Danke, dass Ihr mir zugehört habt, Jungspund. Ich weiß das mehr zu schätzen, als Ihr denkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70134] = { id = 70134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen", description = "Danke, dass Ihr mir zugehört habt, Jungspund. Es gibt einen Gefallen, um den ich Euch bitten möchte.\n\nKeine Sorge. Keine weiteren Geschichten.\n\nAls wir diesen Ort verlassen haben, habe ich eine Art... Zeitkapsel hinterlassen. Könntet Ihr... Könntet Ihr sie mir bringen? Wir haben die Kapsel hinter einer der Säulen am Fuße des Rubinlebensschreins versteckt.\n\nIch habe sie mit einem Siegel versteckt. Wenn Ihr es aktiviert, solltet Ihr die Kapsel sehen können.", sourceObjective = "Holt Veritistrasz' Zeitkapsel.", progress = "Ich bin seltsam... aufgeregt?\n\nAnscheinend freue ich mich darauf, mir die Zeitkapsel anzusehen. Wie... unerwartet.", completion = "Ich danke Euch, Jungspund, Ihr habt mir viel zum Nachdenken gegeben.\n\nAnscheinend habe ich das hier in die Zeitkapsel gelegt. Ich glaube nicht, dass ich noch viel Nutzen dafür habe, aber vielleicht könnt Ihr es ja gebrauchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[70135] = { id = 70135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringende Elementare", sourceObjective = "Tötet 15 Urelementare in der Botschaft von Schwingenrast.", completion = "Für die Drachenschuppenexpedition!\n\n<Kriegsherrin Grimmaxt salutiert Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70136] = { id = 70136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit für Schmerzen", description = "Uff... Einen Moment...\n\nMein erster Auftrag... Instabile Temporalenergie sickert in den Wald... Beeinträchtigt die Wildtiere... Muss die Auswirkungen feststellen und die Magie für die Zeitwanderer sammeln...\n\n<Zera schüttelt ihren Kopf für einen Moment.>\n\nIch hatte gerade ein Rudel Vorquin beobachtet, als ein von Zeitmagie überquellender wildgewordener Bär mich angegriffen hat. Er hat mich überrascht. Ich bin gerade so entkommen.\n\nKönntet Ihr meine fehlende Ausrüstung für mich finden, {class}? Äh, vielleicht müsst Ihr Euch auch um diesen Bären kümmern.", sourceObjective = "Holt den Zeitwandererstab und die Zeitwanderernotizen und erlegt den wahnsinnigen Alpha im Wallenden Wald in Thaldraszus.", progress = "Habt Ihr sie gefunden?", completion = "Habt Dank, dass Ihr all die hochwertige Ausrüstung geborgen habt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70139] = { id = 70139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ein Schutz ist, ist auch ein Weg", description = "Dieses Reservoir wurde einst von drei Schutzsteinen beschützt, die Tyr hier platziert hat.\n\nSie waren dazu gedacht, die auf den Dracheninseln vorherrschende Elementarenergie zu stabilisieren.\n\nAls Ihr mich geweckt habt, konnte ich Schaden am westlichen Schutz spüren. Ich fürchte, dass die Primalisten sich auch an den anderen Schutzen vergangen haben.\n\nSo oder so, wir müssen zunächst den Schaden ermitteln, um herauszufinden, was wir als Nächstes tun.", sourceObjective = "Ermittelt den Schaden an den Schutzsteinen im Tyrholdreservoir.", progress = "Wir müssen herausfinden, welches Ausmaß der Schaden an den Schutzsteinen hat. Ich kann bereits spüren, wie die Elementarenergie beginnt, außer Kontrolle zu geraten.", completion = "Wie erwartet. Wir müssen die fehlenden Schlüsselsteine finden, komme, was wolle.\n\nSonst waren die Verluste, die Zuttiki und ich erlitten haben, umsonst.", sourceObjectiveStatus = "unverified-source-field" }
quests[70146] = { id = 70146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochlandgegenschlag" }
quests[70148] = { id = 70148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Zweck", description = "Hättet Ihr kurz Zeit für mich?\n\nIch mache mir um einen Dracthyr Sorgen, der hier durchgekommen ist. Er hat meinen Partnern und mir allerlei Fragen gestellt, schien mit unseren Antworten allerdings... unzufrieden.\n\nEr nannte sich \"Kralle Ethrethi\". Ich glaube, das macht ihn zu einem ziemlichen Neuling in Euren Rängen, oder?\n\nIch hatte das Gefühl, dass er etwas Hilfe brauchen könnte. Würdet Ihr mir dabei helfen, den Frieden zu wahren?\n\nIch hab ihn drüben mit Kholmar reden sehen.", sourceObjective = "Sucht nach Kralle Ethrethi in der Botschaft von Schwingenrast.", completion = "Ihr habt nicht nur die Stimmung von Kralle Ethrethi, sondern die des gesamten Lagers gehoben! Es kommt nicht alle Tage vor, dass jemand eine zweite Chance bekommt...", sourceObjectiveStatus = "unverified-source-field" }
quests[70149] = { id = 70149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung für das Hochland" }
quests[70150] = { id = 70150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele Welpen, kümmert Euch drum" }
quests[70152] = { id = 70152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelwahnsinn!" }
quests[70154] = { id = 70154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Tor nach Irgendwo", description = "Die Verzauberung wird uns vor der instabilen Energie im Inneren beschützen.\n\nIch öffne den Weg zum nächsten Stein.\n\nSobald Ihr durchgegangen seid, bleibt in der Nähe. Wenn wir ankommen, werde ich Eure Hilfe brauchen, um das Gerät mit Energie zu versorgen.", sourceObjective = "Folgt Warpwirkerin Delandra zum Portal.", completion = "Nicht ganz das, was ich erwartet hatte, aber wir haben es in einem Stück geschafft.\n\nIch muss zugeben, nach allem, was passiert ist, bin ich neugieriger denn je, was sich im Gefäß befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70155] = { id = 70155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schauen, zuhören, atmen", description = "Seid gegrüßt, {race}. Nicht viele halten an, um hallo zu sagen. Und schon gar nicht, um hier etwas zu verweilen. Die meisten haben es auf dem Weg zu ihrem nächsten Reiseziel etwas eiliger.\n\nWürdet Ihr gerne mit mir angeln?", sourceObjective = "Angelt mit Threshrak.", completion = "Kommt zurück, wann immer Ihr wollt, Grünschnabel.", sourceObjectiveStatus = "unverified-source-field" }
quests[70156] = { id = 70156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uraltes Erwachen", description = "Das Portal liegt direkt hinter mir. Schwer zu sagen, wie viel Zeit noch bleibt, bis die schwindende Verzauberung des Gefäßes komplett versiegt oder, schlimmer noch, bricht.\n\nDie dann freigesetzte instabile Energie kann katastrophale Folgen haben.\n\nWollen wir fortfahren?", sourceObjective = "Ermächtigt das Portal.", completion = "Jetzt, da wir, und mit wir meine ich Euch, herausgefunden haben, was diese Dinger sind, bleibt trotzdem unklar, wie viele es davon gibt!\n\nHaltet Eure Augen offen, {name}. Wer weiß, was wir auf den Inseln sonst noch finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[70157] = { id = 70157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gartenpromenade", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70158] = { id = 70158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gartenpromenade - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70159] = { id = 70159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschmack von Heimat", description = "Na endlich! Noch ein Dracthyr, der uns zur Hand geht.\n\nMein Bruder und ich wollten ein paar Essensrationen zubereiten, aber...\n\n<Scaralesh deutet auf seine Umgebung.>\n\nHier ist alles so anders. Man findet hier kaum die Zutaten, die wir früher zum Kochen genommen haben.\n\nAber wir können uns anpassen. Fragt die Horde, ob sie etwas als Ersatz für Gemüse, Proteine und emulgierende Flüssigkeit haben. Dann können wir endlich wieder richtig kochen.", sourceObjective = "Fragt bei Hordenmitgliedern im Drachenschuppenbasislager, ob jemand Euch die notwendigen Zutaten leihen kann.", progress = "Glück gehabt, {name}?", completion = "Die Sachen sehen nicht so aus wie zu Hause, aber wir {race} sind einfallsreich. Wir probieren sie mal aus.\n\nWer weiß, am Ende schmeckt es sogar besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[70160] = { id = 70160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung einer alchemistischen These" }
quests[70161] = { id = 70161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreuz und quer durch die Höhlen", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70163] = { id = 70163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreuz und quer durch die Höhlen - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[70164] = { id = 70164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine ausgetüftelte Gelegenheit", sourceObjective = "Sprecht mit Chronomant Phosildral und Sibrit Klackerpapp in den Ruinen des Lebensgewölbes.", completion = "Unsere Geschichte ist kompliziert, {name}, aber ich bin umso gewillter zu entschlüsseln, was unsere Bestimmung ist... und worin unsere Zukunft liegt. Nun liegt alles in unseren Klauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70166] = { id = 70166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freuden der Malerei", description = "Gefällt Euch meine Sammlung? Das sind alles Werke des größten Malers aller Zeiten, Hudson.\n\nSie sind selten und möglicherweise wertvoll: Er ist ein Einsiedler und hat seit einer Weile nichts Neues gemalt. Oh, wie gerne ich ihn doch mal treffen... oder von ihm lernen würde!\n\nIhr... wirkt recht verwegen. Würdet Ihr ihn für mich aufspüren? H-hier! Nehmt ein paar meiner Werke mit. Vielleicht findet er sie ja beeindruckend!\n\nOder er findet sie schrecklich... oje.", sourceObjective = "Bringt Rauvros' Gemälde der Vorstellung zu Hudson.\n\nBereitgestellter Gegenstand:", completion = "Was ist das? Ein Gemälde?", sourceObjectiveStatus = "unverified-source-field" }
quests[70168] = { id = 70168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traurige kleine Zufälle", description = "Ihr habt den ganzen Weg auf Euch genommen... Es tut mir leid.\n\nMein Hudson hat es früher geliebt, zu malen. Es war sein Leben! Ich weiß nicht, woher diese Blockade kommt.\n\nVor ein paar Wochen hat er auf dem Rückweg von einem Malausflug all seine unvollendeten Gemälde genommen und sie in einem Wutanfall weggeworfen.\n\nIch bitte Euch... könntet Ihr sie ausfindig machen? Vielleicht ist das der Funke, den er braucht.\n\nHudson scheut sich auf der Suche nach den besten Ausblicken nicht vor gefährlichen Orten. Ich hoffe, Ihr seid darauf vorbereitet.", sourceObjective = "Besorgt Hudsons verlorene Gemälde von den finalen Dungeonbossen der Rubinlebensbecken, des Angriffs der Nokhud und der Brackenfellhöhle.", progress = "Lasst mich in Frieden.", completion = "Was? Was habt Ihr getan?\n\nWarum bringt Ihr mir diesen Müll?!", sourceObjectiveStatus = "unverified-source-field" }
quests[70169] = { id = 70169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbst Bäume brauchen Freunde", description = "Ich weiß, dass Ihr und Ran nur versucht, mir zu helfen.\n\nAber ich glaube nicht, dass mir zu helfen ist. Der Funke in mir... mein Wille zu malen... ist einfach... weg.\n\nAber Ran hat recht. Ich bin Euch schuldig, es zumindest zu versuchen.\n\nBringt Euren aufstrebenden Künstlerfreund zu mir.", sourceObjective = "Sprecht mit Rauvros.", progress = "Ich brauche nur eine Chance, mich zu beweisen.", completion = "Ich kann es nicht fassen! Eine Gelegenheit, vom Meister selbst zu lernen!\n\nAch du meine Güte... Ich hoffe, ihm gefallen meine Werke.", sourceObjectiveStatus = "unverified-source-field" }
quests[70170] = { id = 70170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonen austreiben", description = "Ich fürchte, er kann sehr stur sein.\n\nAber ich kann ihn nicht einfach aufgeben. Wir werden es einfach noch einmal versuchen müssen!\n\nEs gibt noch mehr Gemälde da draußen, die er rausgeworfen hat. Und zwar an noch gefährlicheren Orten. Ich hoffe wirklich, dass Ihr der Herausforderung gewachsen seid!", sourceObjective = "Besorgt Hudsons verlorene Gemälde von den finalen Dungeonbossen der Hallen der Infusion, der Akademie von Algeth'ar, des Azurblauen Gewölbes und von Neltharus.", progress = "Was jetzt?", completion = "Schon wieder? Warum bringt Ihr mir immer wieder diese Verbrechen gegen die Kunst?", sourceObjectiveStatus = "unverified-source-field" }
quests[70171] = { id = 70171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glückliche kleine Zufälle", description = "<Ranpiatas Augen werden feucht.>\n\nBin ich es? Bin ich der Grund, dass er den Funken verloren hat?\n\nEr sagt, er liebt mich, aber... Ihr habt gehört, wie es ihm geht, wenn er nicht malt.\n\nIch will nur das Beste für ihn. Wenn es das Beste für ihn ist, dann... werde ich gehen.\n\nEs gibt ein letztes Werk, das er weggeworfen hat. Das letzte Werk, an dem er sich versucht hat, bevor er aufgegeben hat.\n\nIch konnte nicht zusehen, wie er es wegwirft, also habe ich es in unserem Haus versteckt. Bitte... bringt es zu ihm... als Erinnerung.", sourceObjective = "Findet Hudsons letztes Werk.", progress = "Was für ein seltsamer Tuskarr. Wie kann man nur so dickköpfig sein?\n\nIst es das, was es bedeutet, ein Künstler zu sein? Wird mit mir dasselbe passieren? Oh je.", completion = "Das ist dann doch alles etwas zu viel für mich. Ich wollte doch nur von einem Meister lernen, wie man malt!\n\nAber... das hat mich etwas mehr darüber nachdenken lassen, was mir meine Kunst eigentlich selbst bedeutet.\n\nIch glaube... vielleicht habe ich genug vom Malen.\n\nIch werde meine Farben einfach hierlassen... vielleicht was Neues ausprobieren...", sourceObjectiveStatus = "unverified-source-field" }
quests[70172] = { id = 70172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berggeheimnisse" }
quests[70174] = { id = 70174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Shikaar", description = "Sansok Khan ist die fähigste Jägerin unseres Klans. Obwohl sie nicht hören kann, hat sie ihre Fähigkeiten als Jägerin und Anführerin immer wieder bewiesen.\n\nFür uns alle ist sie Mentorin, eine vertrauenswürdige Anführerin und erbitterte Verteidigerin der Maruuk.\n\nEs ist eine Ehre, mit ihr zu sprechen.", sourceObjective = "Trefft Sansok Khan.", progress = "<Sansok Khan mustert Euch bedächtig.>", completion = "<Sansok Khan nickt Euch leicht zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70175] = { id = 70175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgebrochene Leiste", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Weiche Metalle können es einfach nicht mit den Elementen aufnehmen.\n\n<Emilia schüttelt den Kopf, als sie die Leiste von Euch entgegennimmt.>\n\nIch werde sicherstellen, dass diese Leiste an einem sicheren Ort aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70176] = { id = 70176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingesponnen" }
quests[70178] = { id = 70178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionsversorgungspaket", description = "<Forscher/Forscherin>, Eure Entdeckungen sind von unschätzbarem Wert.\n\nDa draußen gibt es noch vieles mehr, das es zu entdecken gilt, und wir haben genau die richtigen Werkzeuge, um Euch dabei zu helfen.\n\nKommt zurück zum Drachenschuppenbasislager und rüstet Euch mit dem Expeditionsversorgungspaket aus.", sourceObjective = "Untersucht die neuen Werkzeuge, die durch das Expeditionsversorgungspaket im Drachenschuppenbasislager erhältlich sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[70179] = { id = 70179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelter Dienst", description = "Seid gegrüßt! Ihr seht ganz stark aus, könnt Ihr mir vielleicht aushelfen?\n\nAzkra und ich sind damit beauftragt, auf diesen Turm aufzupassen. Er befindet sich in einem, wie soll ich sagen, \"bemerkenswerten vorsanierten Zustand\". Als wir mit den Reparaturen begannen, wurden wir von Erdelementaren angegriffen!\n\nAlso dachte ich mir: \"Zefren, warum kümmerst du dich nicht um die Erdelementare und besorgst gleichzeitig ein paar Baumaterialien?\" Und genau da kommt Ihr ins Spiel! Könnt Ihr mir helfen?", sourceObjective = "Beschafft Baumaterialien von Erdelementaren.", progress = "Ich muss sagen, ich freue mich schon darauf, wieder an diesem Turm zu arbeiten, vielleicht bringe ich sogar eine kleine Plakette an zum Gedenken an Eure Hilfe! Ihr wollt doch noch helfen, oder?", completion = "Oh, nein, die sind ja viel bröckeliger als erwartet. Also wenn sie einem an den Kopf geworfen werden, wirken sie wesentlich fester!\n\nNa ja, ich kann sie bestimmt trotzdem zum Bauen verwenden, danke für Eure Hilfe!\n\nVielleicht gibt es hier irgendwo Schlammelementare, mit denen ich sie zusammenkleben kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[70180] = { id = 70180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starthilfe? Kommt sofort!", description = "Einige Leute in der Stadt behaupten, dieses Gerät wäre von dem legendären Titanenhüter Tyr erschaffen worden.\n\nDas Problem ist, dass wir es nicht zum Laufen bekommen! Wir haben alle üblichen Tricks probiert, Auseinanderbauen, Gyroskopie, sanfte Elektroschocks. Bis auf die Elektroschocks hat nichts funktioniert. Moment... ich hatte gerade eine tolle Idee.\n\nSeht Ihr den Gyrokopter dort drüben? Springt rein und seht, ob Ihr diesem Titanending etwas mehr... Saft geben könnt.", sourceObjective = "Helft Greyzik, das mysteriöse Gerät mit Energie zu versorgen.", completion = "Wie energiegeladen Ihr seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[70181] = { id = 70181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erste Herausforderung von Tyr: Finesse", description = "<Als Ihr Euch nähert, strahlt die Inschrift auf der Statue ein sanftes Leuchten aus.>\n\n\"Führt die Macht des Hüters und tragt ihr Licht in eine bessere Zukunft für uns alle.\"", sourceObjective = "Schließt die erste Herausforderung von Tyr im Azurblauen Gebirge ab.", completion = "Gut gemacht. Ihr habt Euch Eure Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[70182] = { id = 70182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der süße Geschmack des Sieges", description = "Auch kleine Dinge können großes Potenzial besitzen. Die abgefüllte Essenz mag sich leicht wie eine Feder anfühlen, aber sie besitzt immense Macht.\n\nBringt sie zur Innovationsmaschine.", sourceObjective = "Kehrt zur Innovationsmaschine in Valdrakken zurück.", completion = "Könnt Ihr das Potential spüren, das von der Flasche ausgeht?", sourceObjectiveStatus = "unverified-source-field" }
quests[70183] = { id = 70183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Spezialisierung: Alchemie", progress = "Welche Weisheit sucht Ihr?", completion = "Geduld, Jungblut. Es gibt noch viel zu lernen.\n\nAber heute gibt es einen Grund zum Feiern, denn Ihr versteht nun mehr als vorher." }
quests[70184] = { id = 70184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Spezialisierung: Schmiedekunst", progress = "Welche Weisheit sucht Ihr?", completion = "Geduld, Jungblut. Es gibt noch viel zu lernen.\n\nAber heute gibt es einen Grund zum Feiern, denn Ihr versteht nun mehr als vorher." }
quests[70185] = { id = 70185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriöse Bestie", description = "<Ihr erkennt einen großen Pfotenabdruck in der Erde. Ihr seht Euch um und stellt fest, dass keine der Kreaturen in der Nähe Pfoten hat, geschweige denn so große.\n\nVielleicht lassen sich die Zentauren beeindrucken, wenn Ihr diese riesige Bestie erlegt.>", sourceObjective = "Findet und tötet die Bestie und bringt etwas als Beweis zu Späherin Tomul.", progress = "Kehrt Ihr von Eurer Jagd zurück?", completion = "<Tomul schaut sich den Pelz an und nickt leicht.>\n\nIhr habt also Konkhular erlegt. Nicht schlecht, Zweifüßer. Viele Monde lang ist er unseren Jägern entwischt. Er hat sich mit seinem Pelz immer perfekt an seine Umgebung angepasst. Vielleicht können unsere Jäger seine Tarnung jetzt zu ihrem eigenen Vorteil nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70186] = { id = 70186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Spezialisierung: Verzauberkunst", progress = "Welche Weisheit sucht Ihr?", completion = "Geduld, Jungblut. Es gibt noch viel zu lernen.\n\nAber heute gibt es einen Grund zum Feiern, denn Ihr versteht nun mehr als vorher." }
