quests[70195] = { id = 70195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Sturm erobert", description = "Berichten zufolge wurden die Nokhud von einem Fremdling begleitet, der noch nie zuvor gesehene Magie wirkt. Dieser Fremdling ist durch unsere Reihen gepflügt wie ein Sturm.\n\nWenn die Nokhud Verbündete haben, die so viel Chaos anrichten können, müssen wir so viel wie möglich über sie herausfinden.\n\nIch habe meinen Ohuna, Altan, entsandt, um den Fremdling ausfindig zu machen. Er ist bisher nicht zurück und deshalb mache ich mir Sorgen. {name}, könnt Ihr nach Hinweisen zu diesem Fremdling suchen und herausfinden, was Altan zugestoßen ist?", sourceObjective = "Rettet Altan und sucht nach Hinweisen zum Fremdling.", progress = "Ich habe einen Verdacht, was die Identität der neuen Verbündeten der Nokhud angeht, aber ich muss mir absolut sicher sein.", completion = "Also befinden wir uns mit den Nokhud und den Primalisten im Krieg. Dann ist es jetzt noch wichtiger, dass wir Ohn'ahra und die Drachen auf unsere Seite bringen.\n\nDanke für Eure Hilfe, {name}, und für Altans Rettung.", sourceObjectiveStatus = "unverified-source-field" }
quests[70196] = { id = 70196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reservatreinigung" }
quests[70197] = { id = 70197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Inseln", description = "Seid Ihr bereit für das Abenteuer Eures Lebens? Ich bin es auf jeden Fall!\n\nUnsere Verbündeten haben sich versammelt und alle Vorräte sind verladen. Worauf wartet Ihr also noch?\n\nTrefft mich bei den Docks von Sturmwind. Zeit, zu den Dracheninseln aufzubrechen!", sourceObjective = "Trefft Toddy Schnurrbart im Hafen von Sturmwind.", completion = "Ihr seht ganz und gar bereit aus. Machen wir uns auf den Weg!", sourceObjectiveStatus = "unverified-source-field" }
quests[70198] = { id = 70198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf zu den Inseln", description = "Unsere Verbündeten versammeln sich in Durotar. Dies ist eine sehr aufregende Zeit!\n\nSchließt Euch uns an, {name}! Zeit, zu den Dracheninseln aufzubrechen!", sourceObjective = "Trefft Naleidea Flussglanz in Durotar.", completion = "Ich bin so aufgeregt! Seid Ihr bereit, unser gemeinsames Abenteuer zu beginnen?", sourceObjectiveStatus = "unverified-source-field" }
quests[70199] = { id = 70199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangen und freilassen: Schuppenbauchmakrele", progress = "Wenn wir diese Stelle überfischen, wird es für niemanden mehr Fisch geben. Nachhaltigkeit ist der Schlüssel.\n\nBringt mir alle Fische, die wieder zurück in die Gewässer sollen.", completion = "Ich werde sie wieder in die Gewässer freilassen. Fischerei ist eine verantwortungsvolle Aufgabe." }
quests[70200] = { id = 70200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangen und freilassen: Tausendbisspiranha", progress = "Wenn wir diese Stelle überfischen, wird es für niemanden mehr Fisch geben. Nachhaltigkeit ist der Schlüssel.\n\nBringt mir alle Fische, die wieder zurück in die Gewässer sollen.", completion = "Ich werde sie wieder in die Gewässer freilassen. Fischerei ist eine verantwortungsvolle Aufgabe." }
quests[70201] = { id = 70201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangen und freilassen: Querflossen-Flügelrossfisch", progress = "Wenn wir diese Stelle überfischen, wird es für niemanden mehr Fisch geben. Nachhaltigkeit ist der Schlüssel.\n\nBringt mir alle Fische, die wieder zurück in die Gewässer sollen.", completion = "Ich werde sie wieder in die Gewässer freilassen. Fischerei ist eine verantwortungsvolle Aufgabe." }
quests[70202] = { id = 70202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangen und freilassen: Himmelblauer Stachelfisch", progress = "Wenn wir diese Stelle überfischen, wird es für niemanden mehr Fisch geben. Nachhaltigkeit ist der Schlüssel.\n\nBringt mir alle Fische, die wieder zurück in die Gewässer sollen.", completion = "Ich werde sie wieder in die Gewässer freilassen. Fischerei ist eine verantwortungsvolle Aufgabe." }
quests[70203] = { id = 70203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangen und freilassen: Temporaler Drachenkopf", progress = "Wenn wir diese Stelle überfischen, wird es für niemanden mehr Fisch geben. Nachhaltigkeit ist der Schlüssel.\n\nBringt mir alle Fische, die wieder zurück in die Gewässer sollen.", completion = "Ich werde sie wieder in die Gewässer freilassen. Fischerei ist eine verantwortungsvolle Aufgabe." }
quests[70204] = { id = 70204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldene Klaue", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Die Drachenschwärme hatten definitiv eine Vorliebe für Gold, nicht wahr? Es ist überall! Und jetzt haben wir es.\n\nIch stelle sicher, dass es hinter Schloss und Riegel aufbewahrt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[70207] = { id = 70207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwanzfragment", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Es muss wiederhergestellt werden... aber es ist eine gute Arbeit. Ich werde es selbst katalogisieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[70209] = { id = 70209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quaken und angreifen" }
quests[70210] = { id = 70210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht vergessene Tradition", description = "Es ist Tradition bei den Aylaag, dass wir, wenn wir in diesem Lager kampieren, zu den Ewigen Kurganen pilgern, und um sichere Reisen bitten und darum, von dem verschont zu bleiben, das unsere Vorfahren heimgesucht hat. Die Anwesenheit der Nokhud macht diese Pilgerreise gefährlich.\n\nWenn es Euch nichts ausmacht, würde ich Euch bitten, diese Tradition für uns weiterzuführen.", sourceObjective = "Platziert Räucherwerk und beseitigt geisterhafte Bestien an den Ewigen Kurganen.", progress = "Klan Nokhud und Ukhel entweihen das spirituelle Land allein schon durch ihre Anwesenheit.", completion = "Ich stehe tief in Eurer Schuld. Es fällt mir schwer, einen Fremdling um Hilfe bei etwas für unseren Klan so Wichtigem zu bitten, aber ich sehe keine andere Möglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[70211] = { id = 70211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscherstampfer", description = "Der Zustrom von Forschern auf die Dracheninseln wird so bald nicht abreißen. Wir müssen unseren Vorrat an Plattenstiefeln des Forschers aufstocken. Sogar Serevit kann die Ansprüche nicht erfüllen, die an solche Stiefel gestellt werden. Macht Euch an die Arbeit und kommt zu mir, wenn Ihr fertig seid.", sourceObjective = "Stellt 2 Plattenstiefel des Forschers für Stahlformerin Kuroko in Valdrakken her.", progress = "Seid Ihr schon fertig?", completion = "Das ist gute Handwerkskunst. Bald werden wir das liebliche Scheppern vieler Plattenstiefel hier in der Gegend hören.\n\nEure Fähigkeiten entwickeln sich gut. Hier habt Ihr etwas, was Ihr studieren könnt, um Eure Schmiedekunst noch mehr zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70212] = { id = 70212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penumbrus" }
quests[70213] = { id = 70213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harkyn Grymmstein" }
quests[70215] = { id = 70215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neugier ist der Schlüssel", description = "Mein Zögern, über diese Symbole zu sprechen, lag nicht daran, dass ich Euch nicht vertraut habe, sondern an der unergründlichen Natur dieser Symbole und auch der Steine, auf denen sie stehen.\n\nJa, Steine. Und zwar mehrere, verteilt über die ganzen Inseln.\n\n<Warpwirkerin Delandra wirft Euch einen Blick zu. Ein Hauch von Neugierde und Aufregung sind in ihren Augen zu erkennen.>\n\nIhr wusstet das nicht.\n\nNun gut. Eure Beharrlichkeit und Eure Bereitschaft, mich aufzusuchen, zeigen mir, dass Ihr Eure jüngste Entdeckung unbedingt verstehen wollt. Vielleicht ist es Zeit, dass wir das im Detail besprechen.", sourceObjective = "Sprecht mit Warpwirkerin Delandra im Lager Antonidas.", completion = "Ich habe ein Gefäß gefertigt, das es ermöglicht, ungezügelte Energie einzufangen und aufzubewahren.\n\nDieses Wissen ist nicht vielen bekannt. Es wäre ratsam, vorsichtig vorzugehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70220] = { id = 70220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenzuflucht", description = "Wir müssen den Rest des grünen Drachenschwarms informieren, dass die Barriere vor dem Uralten Zweig bedroht ist. Gerithus und ich haben eine Menge zu besprechen.\n\n{name}, ich werde Euch mit meinem Mal versehen. Die anderen Drachen, die es erkennen, werden wissen, dass Ihr <mein vertrauenswürdiger Bote/meine vertrauenswürdige Botin> seid.\n\nGeht und versammelt meinen Schwarm. Er muss davon erfahren und sich auf den Kampf vorbereiten.", sourceObjective = "Sprecht mit Wachhauptmann Alowen, Sariosa, Sidra der Heilerin und Viranikus.", progress = "Geht mit meinem Segen.", completion = "Mein Drachenschwarm ist also bereit? Gut. Wir werden unseren Feinden mit allem entgegentreten, was wir haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[70221] = { id = 70221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt Euren Eifer", sourceObjective = "Heda, {name}! Das Handwerkerkonsortium würde Euch gern danken für alles, das Ihr für uns getan habt. Wir würden Euch gerne etwas Eifer des Handwerkers verleihen, kostenlos.\n\nVielleicht könnt Ihr ihn ja nutzen, um einige Bestellungen für uns zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70224] = { id = 70224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Müffelnde Monster" }
quests[70229] = { id = 70229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boku der Mystiker", description = "Die Mystiker wurden vor ein paar Tagen zur Gratwasserzuflucht gerufen, aber ein Mystiker ist geblieben. Sein Name ist Boku. Er befindet sich oben auf dem Hügel am Schrein von Ohn'ahra.\n\nEr ist noch ein Initiand, aber es sollte ihm möglich sein, mit Ohn'ahra Zwiesprache zu halten und ihren Segen zu erhalten. Mit Ohn'ahra an unserer Seite gewinnen wir vielleicht den Krieg, bevor er beginnt.", sourceObjective = "Findet Boku in Teerakai.", completion = "Wer seid Ihr? Hat Euch Ohn'ahra geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[70233] = { id = 70233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Axtmangel", description = "Eine Verwechslung der Bestellungen hat zu einem schweren Mangel an neuen Äxten für unsere Forscher geführt. Wir brauchen dringend mehr Drakoniumäxte und suchen nach Schmieden, die einspringen können. Im Gegenzug lasse ich Euch etwas neues Schmiedewissen zukommen, mit dem Ihr sogar noch epischere Teile herstellen könnt.", sourceObjective = "Stellt 2 Drakoniumäxte für Stahlformerin Kuroko in Valdrakken her.", progress = "Seid Ihr schon fertig?", completion = "Die werden unseren schwindenden Vorrat schön aufstocken.\n\nEure Fähigkeiten entwickeln sich gut. Hier habt Ihr etwas, was Ihr studieren könnt, um Eure Schmiedekunst noch mehr zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70234] = { id = 70234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ständige Hämmern", description = "Die Ambosse kommen nicht zur Ruhe, seit die Dracheninseln erwacht sind. Die Ambosse selbst halten gut, aber unsere Hämmer lassen langsam nach. Um mit der Nachfrage mithalten zu können, müssen wir aufstocken.", sourceObjective = "Stellt 2 Drakoniumschmiedehämmer für Stahlformerin Kuroko in Valdrakken her.", progress = "Seid Ihr schon fertig?", completion = "Man kann nie genug Hämmer haben, nicht wahr?\n\nEure Fähigkeiten entwickeln sich gut. Hier habt Ihr etwas, was Ihr studieren könnt, um Eure Schmiedekunst noch mehr zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70235] = { id = 70235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparaturrechnung", description = "Die Dracheninseln haben seit Jahrtausenden keinen Konflikt wie diesen gesehen. Unsere Arbeit steht außer Frage, aber unter der ständigen Nutzung leidet jede gute Rüstung. Ich habe eine große Bestellung an Serevitreparaturhämmern und brauche alle, die ich bekommen kann, um sie zu erfüllen. Wenn Ihr aushelft, gebe ich Euch gerne mehr Informationen, um Eure Schmiedekunst der Dracheninseln zu verbessern.", sourceObjective = "Stellt 6 Serevitreparaturhämmer für Stahlformerin Kuroko in Valdrakken her.", progress = "Seid Ihr schon fertig?", completion = "Ich hatte noch nie so viele Reparaturhämmer zur Hand! Wollen wir wetten, wie lange es dauert, bis die Kunden sie aufgerieben haben?\n\nWie versprochen bekommt Ihr hier etwas zum Studieren. Ihr könnt Eure Schmiedekunst immer verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70236] = { id = 70236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgelöstes Drachenauge", description = "<Das könnte etwas sein, wonach Emilia Bellersen sucht.>", sourceObjective = "Bringt den Gegenstand zu Emilia Bellersen.\n\nBereitgestellter Gegenstand:", completion = "Oh... seht nur, wie es funkelt! Es ist schwer, es nicht einfach... in meine Tasche zu stecken. Aber ich werde das nicht tun. Ich lege es an einen sicheren Ort, der nicht in meiner Kleidung ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[70239] = { id = 70239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unausgesprochene Reue", description = "Duroz ist alt, krank und stur wie ein Kodo. Nichts konnte ihn davon abhalten, mit dem Luftschiff hierherzufliegen. Alles, was ich machen konnte, war, ihm als Gehstock zu dienen.\n\nIch habe ihn oft genug auf dem Schlachtfeld beobachtet, um zu wissen, wann er Schmerzen verheimlicht. Es geht ihm hier draußen jeden Tag schlechter. Könnt Ihr mir helfen, ihn zu den Tränkebrauern zu bringen? Bier reicht ihm nicht mehr.\n\nWenn Ihr unsere Waffen tragen könnt, kann ich ihm beim Gehen helfen.", sourceObjective = "Geht ein Stück mit Duroz und Kolgar, um nach Hilfe zu suchen.", completion = "<Badoras runzelt besorgt die Stirn, während sein Blick kurz über den alten Orc wandert.>\n\nIch werde ihn untersuchen und sehen, was ich tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[70240] = { id = 70240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmerzbehandlung", description = "Ihr habt ihn gerade rechtzeitig hergebracht. Ich kann erkennen, dass er starke Schmerzen hat, auch wenn er sie gut erträgt. Das müssen wir alle, wenn die Zeit kommt.\n\nIch fürchte, es ist das Alter, das ihn quält, und keine Krankheit, aber vielleicht kann ich sein Leid ein wenig lindern.\n\nWürde es Euch etwas ausmachen, ein paar Knallblumen, Seichtwasserlilien und reines Wasser aus dem Garten in der Nähe zu holen? Wenn Ihr genug davon findet, kann ich daraus ein Schmerzmittel herstellen.", sourceObjective = "Sammelt 5 milchweiße Knallblumen, 3 blühende Schattenlilien und eine gefüllte Lebensbeckenphiole.", progress = "War die Drachenbrut... bereit, irgendetwas zu machen?", completion = "<Duroz nimmt Euch den Trank mit einem flüchtigen, traurigen Lächeln ab. Er wirkt beinahe enttäuscht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70241] = { id = 70241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis zum bitteren Ende", description = "Es ist gerade passiert. Ich... Er hat geschlafen und ich hab nur kurz nicht hingesehen und... Wir sind jeden Tag hierhergekommen, er wollte nur bei den Welpen sitzen. Ich wusste nicht, dass er...\n\n<Kolgars Gesicht ist tränenverschmiert. Er reibt sich mit dem Handrücken über die Augen.>\n\nNein, ich wusste es. Ich wusste es. Aber ich weiß nicht, was ich jetzt tun soll. Was mache ich nur mit ihm?\n\nWürdet Ihr... Würdet Ihr bitte Badoras suchen?", sourceObjective = "Schafft Badoras zu Duroz und Kolgar.", completion = "Ich verstehe. Manchmal kann man nichts mehr tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[70242] = { id = 70242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leben um Leben", description = "Ich spüre, dass sein Freund eine tiefe Narbe in sich trug. Etwas an diesem Ort hat sie wieder geöffnet... vielleicht damit sie diesmal vollständig heilen kann.\n\nJetzt muss Kolgar ebenfalls heilen.\n\nAuf der Terrasse über uns findet Ihr meinen Freund Trellain. Er arbeitet mit den Verzauberern. Sagt ihm, dass ich eines der Gefäße benötige, die er auf der Arbeit verwendet. Er wird Euch bereitwillig eins überlassen.", sourceObjective = "Sammelt ein inaktives Gefäß bei Trellain im Rubinlebensschrein ein.", progress = "Konntet Ihr Trellain finden?", completion = "Danke, {name}. Das sollte passen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70244] = { id = 70244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nokhud an den Kragen", description = "Seit Tausenden von Jahren haben die Teerai das Horn von Drusahl, unsere heiligstes Relikt, bewacht. Mit der Plünderung dieses Dorfes hat Balakar alles verraten, was es bedeutet, Maruuk zu sein. Für ihn kann es keine Erlösung mehr geben.\n\nWir müssen das Horn zurückerobern, bevor Balakar es zerstören kann, und alle noch lebenden Teerai retten. Ich werde Euch begleiten, um diesen falschen Khan persönlich zu richten. Die Nokhud werden den Zorn der Khanam Matra zu spüren bekommen!", sourceObjective = "Betretet das Dorf mit Khanam Matra Sarest und erobert es von den Nokhud zurück.", progress = "Wir haben keine Zeit zu verlieren! Wir müssen das Dorf zurückerobern und das Horn von Drusahl verteidigen!", completion = "Was machen sie mit Ohn'ahra? Das wird Balakar und Koroleth teuer zu stehen kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70268] = { id = 70268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbelebte Erinnerungen", description = "Ihr habt ein teilweise zerstörtes Tagebuch gefunden. Es scheint aus der Sicht einer jungen schwarzen Drachenfrau aus der Zeit vor der Verderbnis geschrieben zu sein.\n\nZwar ist der hintere Teil unleserlich, aber beim Überfliegen des ersten Teils kristallisiert sich ein Name heraus. Veritistrasz.", sourceObjective = "Gebt Veritistrasz das Tagebuch.", progress = "Hallo, Jungspund, es ist schön, Euch wiederzusehen.", completion = "Oh? Was ist das? Ein Tagebuch? Ich frage mich, was darin steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70279] = { id = 70279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut von Drachen", description = "Wie Ihr sicher schon gesehen habt, gibt es in diesem Land Kreaturen, die über ihre normale Größe hinauswachsen.\n\nWir betrachten diese Bestien als von den wilden Göttern gesegnet. Sie werden von Jägern oft als ehrenvolle Ziele angesehen, denn so beweisen sie ihre Stärke. Eine dieser Bestien, die wir Karkidan nennen, befindet sich in der Nähe. Ich wäre sehr beeindruckt, wenn Ihr es schaffen würdet, Karkidan zu erlegen.", sourceObjective = "Tötet Karkidan.", progress = "Wie läuft die Jagd?", completion = "Bewundernswerte Arbeit! Ihr seid den besten Jägern der Teerai ebenbürtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[70299] = { id = 70299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drakonische Defensive", description = "Der Wind brachte Kunde, dass sich Fremde mit Klan Nokhud verbünden, um unsere Drachennachbarn zu bezwingen. Die Primalisten sind eine Geißel im Lande unserer Vorfahren.\n\nTötet sie und bringt mir die Kerne der Elementare, die sie befehligen.", sourceObjective = "Erledigt Primalisten in der Sturmschneise.", progress = "Wir haben lange Zeit mit den Drachen Frieden gehalten. Wir können seine Bedrohung nicht ignorieren.", completion = "Hoffentlich ist Aylaag damit vor dem Zorn der Drachen sicher. Leider können wir Euch abgesehen von dieser bescheidenen Unterstützung nichts anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[70319] = { id = 70319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nergazurai", description = "Mein Onkel erzählte mir viele Geschichten von seinem Kampf gegen einen Hornschreiter namens Nergazurai. Er berichtete von den fuchsienfarbigen Schuppen, die durch die Ebenen sausen, wenn Nergazurai auf der Suche nach Beute ist, von seinen messerscharfen Klauen und seinem giftigen Biss.\n\nIch war gerade auf der Jagd, als ich seine Silhouette erspähte, aber es war zu spät: Er verpasste mir eine üble Bisswunde an der Schulter. Er war so furchtbar, wie mein Onkel beschrieben hatte, aber irgendwie kam ich mit dem Leben davon.\n\nIch muss aber die Infektion von der Bisswunde reinigen. Bitte, sammelt die Reagenzien, die ich brauche. Mir bleibt nicht mehr viel Zeit.", sourceObjective = "Bringt ein Ottukherz, einen Felszahnoberschenkelknochen, eine Hornschreiterschuppe und einen Geiermuskelmagen zu Muqur dem Regenberührten am Baumschrittaußenposten.", progress = "Mein Fieber wird immer schlimmer. Ich fürchte, wenn ich die Infektion nicht bald säubere, wird das mein Ende sein.", completion = "Vielen Dank. Mit diesen Reagenzien sollte ich verhindern können, dass sich die Infektion ausbreitet, und sie hoffentlich ganz beseitigen können. Ich schulde Euch mein Leben.\n\nNehmt Euch auf Euren Reisen vor Nergazurai in Acht. Seine Gier nach Blut ist unersättlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[70335] = { id = 70335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Ausgrabungswerkzeuge", sourceObjective = "Wir wissen Eure Hilfe wirklich zu schätzen. Als kleines Zeichen meiner Dankbarkeit möchte ich Euch eines meiner besonderen Ausgrabungswerkzeuge anbieten. Die übrigen Werkzeuge biete ich auch zum Verkauf an, also kommt gern wieder, wenn Ihr das Set vervollständigen möchtet.\n\nVielen Dank, Abenteurer!", sourceObjectiveStatus = "unverified-source-field" }
quests[70337] = { id = 70337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glutwacht", description = "Seid gegrüßt, Fremdling.\n\nDie Winde brachten Kunde von einer Gruppe, die Zuflucht in den Ruinen von Glutwacht gesucht hat. Sie scheinen sich nur für die Vergangenheit zu interessieren, während wir Zentauren für die Gegenwart unter dem Segen Ohn'ahras leben.\n\nNichtsdestoweniger sind sie Gäste unserer Heimstatt. Ich habe dieses Windspiel für sie angefertigt, damit sie Ohn'ahras Gegenwart wahrnehmen können. Möge es ihnen Freude und Behaglichkeit bereiten.", sourceObjective = "Bringt das Windspiel der Ohn'ir nach Glutwacht.\n\nBereitgestellter Gegenstand:", completion = "Was ist das?\n\nFaszinierend. Es muss sich um ein uraltes Artefakt von höchster Wichtigkeit handeln.\n\nWir brauchen einige Zeit, um es zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70338] = { id = 70338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denkt niemand an die Kinder?!", description = "Wenn Sylvie verstört ist, dann muss das bedeuten, dass ihre Jungen da drinnen sind!\n\nDie Riesen müssen ihre Jungen entführt haben, während sie infiziert und zu schwach war, sie zu retten.\n\nDie Jungtiere sind in einem ziemlich lebhaften Alter, hoffentlich waren sie bisher flink genug, den Riesen zu entkommen...\n\nHier, benutzt mein Unsichtbarkeitsamulett... Schnell, Ihr müsst sie retten, bevor sie gefressen werden!", sourceObjective = "Rettet die Jungen.", completion = "Jetzt, da Sylvie heilt, sind diese Jungen wieder in guten Händen...\n\nÄh, Pfoten...\n\nKlauen?", sourceObjectiveStatus = "unverified-source-field" }
quests[70339] = { id = 70339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tyrs Fußstapfen: Die Ebenen von Ohn'ahra", description = "Obwohl Ihr Eure erste Herausforderung gut gemeistert habt, solltet Ihr nicht glauben, dass Euch alles so leicht gelingt. Hüter Tyr wollte, dass die Innovationsmaschine nur von denen genutzt wird, die würdig sind, sie weise einzusetzen.\n\nWenn Ihr Euch nicht abschrecken lasst, werdet Ihr die zweite Herausforderung auf den Ebenen von Ohn'ahra finden. Ich freue mich darauf, Eure Fähigkeiten zu prüfen, <Abenteurer/Abenteurerin>.", sourceObjective = "Findet die zweite Herausforderung von Tyr auf den Ebenen von Ohn'ahra.", completion = "<Ihr habt das Gefühl, die Statue würde auf Eure Anwesenheit reagieren, als ihr Mechanismus langsam erwacht und sie mit Leben erfüllt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70341] = { id = 70341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wohlverdienter Sieg", description = "Die kleinsten Dinge können die größten Schätze enthalten.\n\nBringt die Essenz zur Innovationsmaschine.", sourceObjective = "Kehrt zur Innovationsmaschine in Valdrakken zurück.", completion = "Könnt Ihr das Potential spüren, das von der Flasche ausgeht?", sourceObjectiveStatus = "unverified-source-field" }
quests[70351] = { id = 70351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gartenfest", description = "Ich habe mich seit Jahren um diesen Garten gekümmert und mich auf den Tag vorbereitet, an dem ich endlich meine Lebensaufgabe annehme. Und nun ist dieser Tag gekommen!\n\nIch liebe alle Bäume und Blumen und Pflanzen... und selbst die Krabbeltiere, die sich dazwischen verstecken. Ich kann den Geist der Natur, den großen Drachengeist, spüren, wenn ich mich um den Garten kümmere.\n\nEs gibt nur noch eines zu tun. Ich werde den großen Drachengeist beschwören, genau wie in den Legenden.\n\n<Akoras Lächeln strahlt vor Freude.>\n\nTrefft mich unten im Garten bei dem Becken, wo ihre Knochen ruhen. Ich erkläre Euch den Rest dort.", sourceObjective = "Sprecht mit Akora bei den Rubinlebensbecken.", completion = "Ausgezeichnet. Jetzt kann die Arbeit anfangen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[70352] = { id = 70352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Schuppen von den Augen", description = "Ihr da, Fremdling! Ihr habt schon mal Protodrachen getötet, nicht wahr?\n\nDann möchte ich meinen, dass wir mit Eurer Erfahrung und meinen Jagdkünsten zusammen eine ganze Reihe von ihnen zur Strecke bringen könnten. Hier in der Nähe liegen Quellen, die drakonische Bestien anlocken.\n\nHelft mir, meiner törichten besseren Hälfte zu beweisen, dass ich die bessere Jägerin bin.", sourceObjective = "Tötet Flunker und territoriale Protodrachen mit Toluiqi.", sourceObjectiveStatus = "unverified-source-field" }
quests[70355] = { id = 70355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemie der Dracheninseln" }
quests[70357] = { id = 70357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekunst der Dracheninseln" }
quests[70358] = { id = 70358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekunst der Dracheninseln", sourceObjective = "Seid Ihr ebenfalls zu den Inseln aufgebrochen, um neue Waffen und Rüstung zu schmieden? Ich arbeite jetzt schon eine Weile mit diesem neuen Erz... Kann Euch vielleicht den ein oder anderen Tipp geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[70359] = { id = 70359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingenieurskunst der Dracheninseln" }
quests[70360] = { id = 70360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberkunst der Dracheninseln", sourceObjective = "Diese Inseln strotzen nur so vor arkaner Macht!\n\nIhr seht aus, als hättet Ihr Ahnung von Verzauberungen. Wollt Ihr etwas Beeindruckendes sehen?\n\nIch kann Euch neue Verzauberungen beibringen, die nur auf den Dracheninseln zu finden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[70361] = { id = 70361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inschriftenkunde der Dracheninseln" }
quests[70362] = { id = 70362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lederverarbeitung der Dracheninseln", sourceObjective = "Es gibt verschiedene Arten, ein Tier zu häuten.\n\nAber das wisst Ihr natürlich bereits, Lederverarbeiter. Wisst Ihr allerdings auch schon, wie man mit Protodrachenleder arbeitet?\n\nIch kann Euch neue Lederverarbeitungstechniken beibringen, die sich auf den Dracheninseln als nützlich erweisen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[70363] = { id = 70363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürschnerei der Dracheninseln", sourceObjective = "Seid gegrüßt und willkommen auf den Dracheninseln.\n\nDie Klinge an Eurer Seite zeigt mir, dass Ihr ein erfahrener Kürschner seid, wobei Ihr neu in diesen Landen wirkt.\n\nSoll ich Euch zeigen, wie man die Tiere der Dracheninseln häutet?", sourceObjectiveStatus = "unverified-source-field" }
quests[70364] = { id = 70364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuterkunde der Dracheninseln" }
quests[70365] = { id = 70365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juwelierskunst der Dracheninseln" }
quests[70366] = { id = 70366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneiderei der Dracheninseln", sourceObjective = "Drakonisches Weben ist eine uralte Kunst. Es dauert Jahrzehnte, wenn nicht Jahrhunderte, es zu meistern. Nur ein weiterer Grund, heute damit zu beginnen!\n\n<Krillonn betrachtet Eure Hände.>\n\nKeine Sorge, wir haben Werkzeuge für jene ohne eigene Klauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70368] = { id = 70368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufsexamen", description = "Hallo! Hättet Ihr Interesse daran, mit dem Handwerkerkonsortium zusammenzuarbeiten, um reichlich Gewinn zu machen und Kunden in ganz Azeroth mit wertvollen Gütern und Dienstleistungen zu versorgen?\n\n... Hmm? Ihr habt keinen Beruf? Was für eine verpasste Gelegenheit!\n\n<Haephesta denkt kurz nach.>\n\nIch weiß! Ich stelle Euch eine Reihe von Fragen über Eure Persönlichkeit und schon finden wir heraus, welcher Beruf am besten zu Euch passt! Was sagt Ihr?", sourceObjective = "Macht Haephestas Persönlichkeitstest, um herauszufinden, welcher Beruf am besten zu Euch passt.", progress = "Tests sind die Lösung für alles!", completion = "Ich bin froh, dass wir einen Beruf finden konnten, der zu Euch passt!\n\nViel Erfolg für Eure Ausbildung! Kehrt zum Handwerkerkonsortium zurück, sobald Ihr mehr Erfahrung gesammelt habt. Wir bieten Euch viele Chancen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70369] = { id = 70369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Vergangenheit" }
quests[70370] = { id = 70370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufsexamen", description = "Hallo! Hättet Ihr Interesse daran, mit dem Handwerkerkonsortium zusammenzuarbeiten, um reichlich Gewinn zu machen und Kunden in ganz Azeroth mit wertvollen Gütern und Dienstleistungen zu versorgen?\n\nAusgezeichnet! Welche beiden Berufe habt Ihr gelernt?\n\n... Hmm? Ich habt nur einen Beruf? Was für eine verpasste Gelegenheit!\n\n<Haephesta denkt kurz nach.>\n\nIch weiß! Ich stelle Euch eine Reihe von Fragen über Eure Persönlichkeit und schon finden wir heraus, welcher weitere Beruf am besten zu Eurem bisherigen Beruf passt! Was sagt Ihr?", sourceObjective = "Macht Haephestas Persönlichkeitstest, um herauszufinden, welcher Beruf am besten zu Euch passt.", completion = "Ich bin froh, dass wir einen Beruf finden konnten, der zu Euch passt!\n\nViel Erfolg für Eure Ausbildung! Kehrt zum Handwerkerkonsortium zurück, sobald Ihr mehr Erfahrung gesammelt habt. Wir bieten Euch viele Chancen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70371] = { id = 70371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesschwingengurlugull!", description = "Todesschwingengurlugull! Todesschwingengurlugull! Todesschwingengurlugull tögrbrrl!!\n\nBrrruuummm blürglg!!\n\n<Ihr braucht keinen Dolmetscher, um zu verstehen, dass ihr die Murlocversion von Todesschwinge zur Strecke bringen sollt. Bevor Ihr zustimmen oder ablehnen könnt, hört Ihr schon das Brüllen eines Maschinenmotors auf Euch zukommen!>", sourceObjective = "Steigt in den Springer ein und besiegt Todesschwingengurlugull!", progress = "Todesschwingengurlugull tögrbrrl!", completion = "Lrgktrr O'Glrlrlrl!\n\n<Die Murlocs feiern Eure Heldentaten!>", sourceObjectiveStatus = "unverified-source-field" }
quests[70373] = { id = 70373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesschwingengurlugull!", description = "Todesschwingengurlugull! Todesschwingengurlugull! Todesschwingengurlugull tögrbrrl!!\n\nBrrruuummm blürglg!!\n\n<Ihr braucht keinen Dolmetscher, um zu verstehen, dass ihr die Murlocversion von Todesschwinge zur Strecke bringen sollt. Bevor Ihr zustimmen oder ablehnen könnt, hört Ihr schon das Brüllen eines Maschinenmotors auf Euch zukommen!>", sourceObjective = "Steigt in den Springer ein und besiegt Todesschwingengurlugull!", progress = "Todesschwingengurlugull tögrbrrl!", completion = "Frrg drg Allrghnnge!\n\n<Die Murlocs feiern Eure Heldentaten!>", sourceObjectiveStatus = "unverified-source-field" }
quests[70374] = { id = 70374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himia die Gesegnete", description = "Die Elemente beanspruchen dieses Land für sich und begrüßen Euer Eindringen nicht.\n\nOh, Elemente, habt Ihr unseren Beschützer vergessen...? Luft! Unsichtbar, doch allgegenwärtig und lebenswichtig für jegliche Existenz. So leicht vergessen, wie man sie einatmet. Nachdem Ihr mir gegenübergestanden habt, werdet Ihr es nie wieder vergessen.", sourceObjective = "Besiegt die Elemente.", completion = "Ihr seid also Himia der Gesegneten begegnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70376] = { id = 70376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweite Herausforderung von Tyr: Macht", description = "<Als Ihr Euch nähert, strahlt eine Inschrift auf der Statue ein sanftes Leuchten aus.>\n\n\"Führt die Macht des Hüters und zeigt die unerschrockene Entschlossenheit der Standhaften.\"", sourceObjective = "Schließt die zweite Herausforderung von Tyr auf den Ebenen von Ohn'ahra ab.", completion = "Gut gemacht, Ihr habt Euch einmal mehr eine Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[70377] = { id = 70377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heruntergekommene Mode", description = "<Eine abscheuliche Sonnenbrille tropft nur so von Schleim, aber sie sieht sehr teuer aus.\n\nJemand vermisst sie sicherlich. Dieser Stil ist gerade heiß begehrt.>", sourceObjective = "Findet den Besitzer der Sonnenbrille.", progress = "Ich kann mich nicht ohne meine Sonnenbrille im VIP-Bereich sehen lassen!\n\nSeht Ihr, ich habe mir einen Gleiter geschnappt und einige GROSSARTIGE Bilder geschossen. Ich habe nach unten geschaut und alle diese winzigen Elementare gesehen, nicht größer als Ameisen! Ich dachte, ha, ameisengroße Elementare, was für ein tolles Motiv.\n\nAber als ich dort ankam, waren sie mindestens dreimal so groß wie Ameisen. Ein schlammiger hat mich verfolgt, aber ich bin sehr schnell. Ich will gar nicht darüber nachdenken, was mit meiner Sonnenbrille passiert ist...", completion = "Meine Sonnenbrille?! Ihr erwartet eine Belohnung, schätze ich. Ihr hättet sie wenigstens säubern können.\n\n<Zeldis haucht sie an und wischt sie ab.>\n\nIch glaube, ich kann einige kleine Münzen für Euch entbehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[70382] = { id = 70382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Rubinlebensschrein-Schleife" }
