quests[70413] = { id = 70413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Glutstrom-Flug" }
quests[70414] = { id = 70414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wankender Boden", description = "Im Namen von Khaz'goroth, was geht hier vor?\n\nDieses Magma hat wirklich seinen eigenen Willen und verzehrt die elementaren Höhlensteine von unten. Hier ist nicht bloß Meister Zufall am Werke... Ich werde dahinterkommen!\n\nPlatziert diese zerschmetternden Totems neben jedem der gefangenen Elementare, um sie zu befreien!", sourceObjective = "Platziert die zerschmetternden Totems, um die gefangenen Höhlensteine zu befreien.", completion = "Gute Arbeit. Wir brauchen elementare Verbündete, wenn wir das Geheimnis der seltsamen Ereignisse hier lüften wollen.", sourceObjectiveStatus = "unverified-source-field" }
