quests[70436] = { id = 70436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Kreuz und quer durch die Höhlen" }
quests[70437] = { id = 70437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Tyrhold", description = "Jahrhunderte sind vergangen, seit die Schwärme zuletzt Tyrhold besucht haben.\n\nDennoch müssen wir dorthinreisen und herausfinden, ob der Mutterschwurstein noch genutzt werden kann.\n\nSprecht am Sitz der Aspekte mit mir. Wir müssen in Erfahrung bringen, welche Gefahren uns bei Tyrs ehemaliger Festung erwarten.", sourceObjective = "Trefft Alexstrasza beim Sitz der Aspekte.", progress = "Schön, Euch zu sehen, {name}.", completion = "Hier scheint es frei genug zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[70438] = { id = 70438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegende Fische", description = "Die Fische könnten etwas besser beißen, meint Ihr nicht?\n\nDa kommt mir eine Idee. Der Legende nach waren diese Seen und Flüsse nicht immer voller Fische. Angeblich wurden diese Wasserlöcher mit Fischen bestückt, als die Drachen darüber segelten und sie fallen ließen! Könnt Ihr das glauben?\n\nVielleicht könntet Ihr es mit Eurem Drachen mal versuchen?", sourceObjective = "Sammelt Fische, um das Angelloch zu bestücken, und besteigt Euren Drachen, um sie von oben abzuwerfen.", completion = "Ha! Die Legenden sind wahr, fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[70439] = { id = 70439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildes Arkana" }
quests[70440] = { id = 70440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tote Augen" }
quests[70442] = { id = 70442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutiges Bankett" }
quests[70444] = { id = 70444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Felder der Wildheit", description = "Auf die mutigsten Shikaar!\n\nVersammelt Eure besten Kämpfer und geht zu den Feldern der Wildheit. Vielleicht werdet Ihr zum mächtigsten von allen gekrönt!\n\nBeweist Eure Kraft. Zeigt uns Eure Kampfeskünste!\n\nEs gelten die Teilnahmebedingungen.", sourceObjective = "Trefft Gurgthock an den Feldern der Wildheit.", completion = "Hey, Ihr habt zu wenig Beine.\n\nAch, sei's drum.", sourceObjectiveStatus = "unverified-source-field" }
quests[70446] = { id = 70446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Geschichte", description = "Beim Erforschen der Archive habe ich Verweise gefunden, die darauf hindeuten, dass es sich beim Obsidianobservatorium um einen Ort von persönlicher Bedeutung für den Erdwächter handelt. Ich kann nur vermuten, welches Wissen sich dort über die Geschichte unseres Schwarms verbirgt.\n\nIm Anbetracht von Glutthals Interesse an diesem Thema habe ich sie von meiner Entdeckung in Kenntnis gesetzt. Ich bete nur, dass das kein Fehler war.\n\nSie ist voraus, um etwas Aufklärung zu betreiben. Bitte behaltet sie im Auge. Sie ist eine kompetente Soldatin, aber dieses Thema ist ziemlich... beängstigend. Wer weiß, worauf Ihr stoßt.", sourceObjective = "Trefft Glutthal am Obsidianobservatorium.", completion = "Ich bin zuversichtlich, mit allem, worauf wir stoßen, klarkommen zu können. Dennoch, im Anbetracht der Lage... war es weise von Edress, Euch als Begleitung für mich zu entsenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[70450] = { id = 70450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Otterabwehr", description = "Hallo, <mein Freund/meine Liebe>. Diese garstigen Ottuks hier klauen mir ständig meinen Fang!\n\nIch persönlich würde sie einfach in die Luft jagen, aber unsere Tuskarrfreunde sind von der Idee wenig angetan. Ich habe deshalb diese Ottukabwehrapparatur MK-H4I entwickelt, aber... leider bin ich kein besonders guter Schwimmer.\n\nIhr scheint mir eher fürs kühle Nass gemacht zu sein. Also seid doch so gut, aktiviert das Gerät und schwimmt ein paar Runden, um sie zu vertreiben, hm?", sourceObjective = "Vertreibt die lästigen Ottuks.\n\nIhr könnt nur ein zusätzliches Fischernetz pro Tag freischalten.", completion = "Hey! Sehr gut gemacht, Jungchen. Dann wollen wir mal ordentlich Köder auswerfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70501] = { id = 70501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdschein", description = "Ah, seid Ihr endlich bereit, Euch als <Jäger/Jägerin> zu beweisen? Denkt daran, dass es nicht einfach darum geht, umherzurennen und alles zu erlegen, was sich bewegt. Die Shikaar jagen bewusst. Wir jagen, um den Klan zu nähren und einzukleiden, um unsere Stärke gegen mächtige Feinde zu beweisen und um die Natur im Gleichgewicht zu halten.\n\nWir jagen das Land nicht leer, wir säen währenddessen die Saat für künftige Große Jagden. Zeigt uns, dass Ihr imstande seid, diese Anweisungen zu befolgen, dann dürft Ihr <einer/eine> von uns werden.\n\nIch habe jedoch wenig Vertrauen, dass Eure Begleitung dort Erfolg hat.", sourceObjective = "Schließt die Übungsaufgabe für die Große Jagd ab.", progress = "Habt Ihr Eure Übung absolviert?", completion = "Hervorragend! Ihr seid bereit, bei Großen Jagden dabei zu sein!\n\nBitte gebt diesem Nesingwary Jr. Bescheid, dass Jagen mehr ist als sinnloses Töten und dass er in unserem Kreise nicht willkommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[70502] = { id = 70502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saubere Luft" }
quests[70503] = { id = 70503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrs Wachsamkeit", description = "Leichen, kaputtes Getriebe, unkontrollierte Titanenenergie... Was für eine Missachtung der Sicherheitsvorschriften... und des Protokolls! Wie es aussieht, haben sie diesen Stein gefunden, aber er war instabil und ist zersplittert.\n\nGlücklicherweise bin ich besonders gut darin, magische Geräte zu reparieren.\n\nAber bevor ich den Stein neu formen kann, müssen wir jedes einzelne Teil einsammeln.", sourceObjective = "Sammelt die Bruchstücke des Steines.", progress = "Ich glaube es nicht. Es ist alles da! Gut gemacht.", completion = "Ich gehe ins Basislager zurück und lasse meine Leute den Stein rekonstruieren. Keine Sorge, {name}, Artefaktwiederherstellung ist unsere Spezialität.", sourceObjectiveStatus = "unverified-source-field" }
quests[70507] = { id = 70507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrs Einsicht", description = "Habt Ihr auf Eurem Weg hierher Szar Skeleth gesehen? Das ist diese Turmruine im Nordosten.\n\nWir haben hier eine Art gute-Nachricht-schlechte-Nachricht-Situation. Die gute Nachricht ist, dass der Stein bereits gefunden wurde. Die schlechte Nachricht ist, dass er von den Splitterflammen gefunden wurde, genauer gesagt von einer magiebegabten Dracthyr namens Makko. Und Makko verwendet den Stein, um die Gorlocs zu kontrollieren.\n\nUnd habe ich bereits erwähnt, dass Makko vom Missbrauch des Steins verrückt geworden ist?\n\nNun, viel Glück!", sourceObjective = "Bergt Tyrs Einsicht.", progress = "Gorlocs eignen sich wohl doch nicht sonderlich als Leibwächter, was? Ich frage mich, wie gefährlich sie gewesen wäre, hätte sie ihren Verstand behalten.", completion = "Ihr habt ihn! Sorgt Euch nicht um mich. Wir sollten ihn ohne Probleme handhaben können, solange wir nicht versuchen, irgendetwas Verrücktes damit anzustellen. Zum Beispiel, kleine Fischmonster zu kontrollieren oder dergleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70509] = { id = 70509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritte Herausforderung von Tyr: Beharrlichkeit", description = "<Diejenigen, die mit den Inseln erwacht sind, haben die Schöpfungen des Hüters Tyr nicht sehr gut behandelt. Vielleicht hilft es, wenn Ihr die fehlenden Teile der Staute findet.>", sourceObjective = "Findet die fehlenden Teile und repariert die kaputte Statue.", progress = "<Als Ihr Euch nähert könnt Ihr die Wärme der Titanenenergie spüren, die einmal mehr durch die Statue fließt.>", completion = "Gute Arbeit, wie immer. Ich beginne zu sehen, dass Tyrs Vertrauen in die Zukunft nicht grundlos war.", sourceObjectiveStatus = "unverified-source-field" }
quests[70510] = { id = 70510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegreich", description = "Einmal mehr bitte ich Euch, diese Essenz zur Innovationsmaschine zu bringen.", sourceObjective = "Kehrt zur Innovationsmaschine in Valdrakken zurück.", completion = "Ist Euch aufgefallen, dass jede Flasche heller leuchtet, wenn Ihr sie herbringt? Das zeigt, dass Ihr dazu erwählt seid, diesen Weg zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70526] = { id = 70526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rennen der Ebenen von Ohn'ahra", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren." }
quests[70529] = { id = 70529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt sie heim" }
quests[70530] = { id = 70530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfungswoche", description = "Den Studenten an der Akademie von Algeth'ar gehen die Lösungen aus... schon wieder. Verzeiht, doch ich würde Euch bitten, mehr alchemistische Lösungen des Drachen zu sammeln, damit sie ihre Studien fortführen können.", sourceObjective = "Stellt 5 alchemistische Lösungen des Drachen mit dem Rezept 'Gemischressourcen zurückgewinnen' für Conflago in Valdrakken her.", progress = "Die Studenten werden ungeduldig.", completion = "Ausgezeichnet, wir werden die Prüfungen doch nicht absagen müssen. Immerhin kann man eine Prüfung nicht ohne Lösungen ablegen!\n\nHier, studiert das. Auch für einen fähigen Alchemisten gibt es immer Neues zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70531] = { id = 70531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manamarkt", sourceObjective = "Stellt 10 lufterfüllte Manatränke für Conflago in Valdrakken her.", progress = "Unsere Kunden warten.", completion = "Vielen Dank, {name}. Meine Alchemie ist brillant, aber mein Kundendienst lässt zu wünschen übrig. Ich bin froh, dass Ihr mir mit diesen Bestellungen geholfen habt.\n\nHier, studiert das. Auch für einen fähigen Alchemisten gibt es immer Neues zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70532] = { id = 70532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Plünderer", sourceObjective = "Stellt 10 erfrischende Heiltränke für Conflago in Valdrakken her.", progress = "Mit jedem verschwendeten Moment werden die Primalisten stärker.", completion = "Vielen Dank, {name}. Das wird die Gesundheit unserer verletzten Champions wiederherstellen und die Primalisten eine weitere Woche in Schach halten.\n\nHier, studiert das. Auch für einen fähigen Alchemisten gibt es immer Neues zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70533] = { id = 70533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trunk, neu geölt", sourceObjective = "Stellt 6 Schauderfeueröle für Conflago in Valdrakken her.", progress = "Ein Werkstück ohne Schauderfeueröl ist wie ein Essen ohne Salz.", completion = "Wunderbar, habt Dank. Nutzt immer ein Fertigungsreagenz wie Schauderfeueröl für ausgezeichnete Handwerkskunst.\n\nHier, studiert das. Auch für einen fähigen Alchemisten gibt es immer Neues zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70539] = { id = 70539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und Ihr dachtet, sie bringen nichts", description = "He, Fünkchen, wisst Ihr, was alle brauchen und jeder vergisst, wenn sie auf ihren Drachen herumfliegen wollen? Schutzbrillen.\n\nUnd wisst Ihr auch, was heute ausverkauft ist? Schutzbrillen.\n\nUnd wisst Ihr, was ich jetzt gerade von Euch brauche? Ganz recht!", sourceObjective = "Stellt 2 Vielmeilenvergrößerungsgläser für Klickiklack Schmetterschlag in Valdrakken her.", progress = "<Klickiklack murmelt vor sich hin, während sie nach etwas sucht.>", completion = "Wunderbar! Die sehen perfekt aus, danke!\n\nHier, nehmt diese Baupläne. Ich wette, darauf findet Ihr etwas, das Ihr noch nicht wusstet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70540] = { id = 70540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Freund des Ingenieurs", description = "He, Fünkchen, Habt Ihr mein...\n\nÄhm... gebt mir doch das...\n\nDas ist es! Ich glaube, es ist an der Zeit, dass wir ein paar mehr Werkzeuge in diesem Laden haben, Ihr wisst, was ich sagen will?", sourceObjective = "Stellt 2 drakoniumummantelte Samophlange für Klickiklack Schmetterschlag in Valdrakken her.", progress = "<Klickiklack murmelt vor sich hin, während sie nach etwas sucht.>", completion = "Endlich! Ohne diese Dinger komme ich mir vor, als müsste ich mit hinter dem Rücken gefesselten Händen arbeiten.\n\nHier, nehmt diese Baupläne. Ich wette, darauf findet Ihr etwas, das Ihr noch nicht wusstet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70541] = { id = 70541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdtaktiken: Begleiter", description = "Euer Ruhm bei den Maruuk wächst. Ihr könnt nun an der Seite eines zähen Bakars oder flinken Ohunas kämpfen.", sourceObjective = "Wählt, ob Ihr auf der großen Jagd an der Seite eines Bakars oder Ohunas kämpfen möchtet.", completion = "Behandelt Euren Jagdbegleiter mit Treue und Respekt, dann wird er Euer Leben mit seinem schützen.\n\nKehrt zurück, wenn Ihr mehr Ruhm gesammelt habt, dann werde ich Euch weiter ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[70542] = { id = 70542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rennen des Azurblauen Gebirges", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren." }
quests[70545] = { id = 70545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 8000...?", description = "He, Fünkchen, ich stecke mitten in einem Geheimprojekt. Die Leute werden durchdrehen! Aber mir ist das Wesentliche ausgegangen. Seid doch so lieb und besorgt mir einige Bolzen.", sourceObjective = "Stellt 10 Handvoll Serevitbolzen für Klickiklack Schmetterschlag in Valdrakken her.", progress = "<Klickiklack murmelt vor sich hin, während sie nach etwas sucht.>", completion = "Oooooh...! <Klickiklack lacht vor sich hin, während sie wohl darüber nachdenkt, wie sie diese Teile einsetzen wird.>\n\nHier, nehmt diese Pläne. Ich wette, darauf findet Ihr etwas, das Ihr noch nicht wusstet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70549] = { id = 70549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leichte Beute" }
quests[70550] = { id = 70550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen im Konvent", description = "Wir könnten Eure Hilfe brauchen.\n\nDie Splitterflammen haben die Kontrolle über den Großteil des Kobaltkonvents erlangt.\n\nBitte, helft uns im Kampf gegen sie. Wir sind zwar nicht viele, aber auch wir können das eine oder andere tun, um Euch zu helfen.", sourceObjective = "Sprecht mit Xavin im Kobaltkonvent, um zu sehen, welche Möglichkeiten die Umgebung zu bieten hat.", progress = "Wir können alle Hilfe brauchen, die wir bekommen.", completion = "Sobald wir mehr Kontrolle über den Kobaltkonvent haben, können wir unsere Verbündeten besser im Kampf gegen die Splitterflammen unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70557] = { id = 70557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fernrohre fern", description = "Großartige Geräte, Fünkchen, heute habe ich was großes für Euch!\n\nScheinbar ist unter den Jägern ein Feuerwerkstrend ausgebrochen. Sie versuchen, die Enten damit in die Luft aufzuscheuchen. Ich wette, die Enten sind zu klug für sowas, aber das hindert uns ja nicht daran, Profit aus der Sache zu schlagen! Seid Ihr dabei?", sourceObjective = "Stellt 15 bronzene Feuerflieger für Klickiklack Schmetterschlag in Valdrakken her.", progress = "<Klickiklack murmelt vor sich hin, während sie nach etwas sucht.>", completion = "Danke, Fünkchen! Das sollte ausreichen, bis ihnen ein neuer haarsträubender Plan einfällt...\n\nHier, nehmt diese Pläne. Ich wette, darauf findet Ihr etwas, das Ihr noch nicht wusstet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70558] = { id = 70558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desillusionierte Illusionen", description = "Mein Inschriftenlehrling, Ihr hättet zu keiner besseren Zeit kommen können.\n\nEs gab einen schrecklichen Unfall! Das ganze Illusionspergament, das ich bestellt habe, hat sich als echt herausgestellt! Könnt Ihr das glauben? Denken die, wir spielen hier ein Spiel? Jemand könnte verletzt werden!\n\nKönntet Ihr diese Situation bereinigen und einige echte Illusionen herstellen?", sourceObjective = "Stellt 5 Illusionspergamente: Zauberschild für Talendara in Valdrakken her.", progress = "Habt Ihr die Inschriften, die ich brauche?", completion = "Tausend Dank, mein Inschriftenlehrling.\n\nBitte nehmt diese Glyphen als Zeichen meiner Dankbarkeit. Vielleicht könnt Ihr sie ja studieren, um damit Eure eigenen Verfahren zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70559] = { id = 70559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federleichte Hilfe", description = "Mein Inschriftenlehrling, ich freue mich, Euch zu sehen.\n\nHeute Morgen habe ich einige Novizen gebeten, sich an der Inschriftenkunde zu versuchen. Aber sie haben alle mit viel zu viel Druck geschrieben und die Spitzen ihrer Federkiele abgebrochen!\n\nIch frage nur ungern, aber könntet Ihr einige Federkiele herstellen, um das Lager zu füllen?", sourceObjective = "Stellt 2 befestigte Federkiele des Schreibers für Talendara in Valdrakken her.", progress = "Habt Ihr neue Federkiele für meine Lehrlinge?", completion = "Vielen Dank, mein Inschriftenlehrling. Ich weiß nicht, was ich ohne Euch tun würde.\n\nBitte nehmt diese Glyphen als Zeichen meiner Dankbarkeit. Vielleicht könnt Ihr sie ja studieren, um damit Eure eigenen Verfahren zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70560] = { id = 70560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das mächtigste Werkzeug: Gute Dokumentation", description = "Mein Inschriftenlehrling, seid Ihr heute in der Stimmung, zu schreiben? Die Drachenschuppenexpedition hat unzählige Notizen von ihren Abenteuern mitgebracht und uns gebeten, ihre Zettelwirtschaft zu einem ordentlichen Kompendium zusammenzufassen, in dem sie unterwegs nachschlagen können. Ach, aber meine Hand ist heute einfach nicht für diese Aufgabe gemacht. Darf ich mich noch einmal an Euch wenden?", sourceObjective = "Stellt 2 Kompendien des Kernforschers für Talendara in Valdrakken her.", progress = "Habt Ihr die Kompendien geschrieben?", completion = "Vielen Dank, mein Inschriftenlehrling, ich danke Euch.\n\nBitte nehmt diese Glyphen als Zeichen meiner Dankbarkeit. Vielleicht könnt Ihr sie ja studieren, um damit Eure eigenen Verfahren zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70561] = { id = 70561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schreibertragödie", description = "Mein Inschriftenlehrling! Es ist schrecklich, einfach nur unerträglich!Ich kann es nicht fassen, wie soll ich mit meinem Leben weitermachen?\n\n<Talendara bricht in Tränen aus.>\n\nIch... habe keine Tinte mehr! Könntet Ihr bitte welche abfüllen?", sourceObjective = "Stellt 5 lodernde Tinte für Talendara in Valdrakken her.", progress = "Habt Ihr die Tinte hergestellt?", completion = "Vielen Dank, mein Inschriftenlehrling. Wenn nur ein Magier Euch duplizieren könnte...\n\nBitte nehmt diese Glyphen als Zeichen meiner Dankbarkeit. Vielleicht könnt Ihr sie ja studieren, um damit Eure eigenen Verfahren zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70562] = { id = 70562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine für Installateure", description = "<Juwelier/Juwelierin>, was haltet Ihr von einer Gelegenheit, Eure Schürftechniken zu verbessern?\n\nDie Architekten und Installateure der Drachenschuppenexpedition haben uns aufgetragen, für den Bau eines neuen Badehauses einige Steine zu besorgen. Ich glaube, das ist eine angemessene Aufgabe, um Euch zu beschäftigen und Eure Feinmaurerei zu üben.", sourceObjective = "Stellt 15 zerbröckelnde Steine für Tuluradormi in Valdrakken her.", progress = "Habt Ihr die Steine?", completion = "Gute Arbeit, {name}.\n\nHier, ich habe diese Steine geschliffen. Ihr könnt sie studieren, um Eure Juwelierskunst zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70563] = { id = 70563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausstellung", description = "Oh, <Juwelier/Juwelierin>, was haltet Ihr von einer Gelegenheit, Eure Juwelenschleiferei zu verbessern?\n\nIch wollte einige unterschiedliche Schliffe ausstellen und ich schätze, ich könnte auch für Eure Edelsteine einen Schaukasten bereitstellen, wenn Ihr Euch beeilt. Bringt mir nicht weniger als die beste Qualität für diese Demonstration.", sourceObjective = "Stellt unterschiedliche Edelsteine für Tuluradormi in Valdrakken her.", progress = "Sind Eure Edelsteine eine Ausstellung wert?", completion = "Fein, ich schätze, die sind gut genug.\n\nHier, ich habe diese Steine geschliffen. Ihr könnt sie studieren, um Eure Juwelierskunst zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70564] = { id = 70564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brillant", description = "<Juwelier/Juwelierin>, eine Ausstellung steht an, aber ich befürchte, dass die Besucher die wahre Schönheit der einzelnen Schliffe ohne die richtigen Linsen nicht erkennen können.\n\nSie müssen nichts Besonderes sein. Stellt nur ein paar Kopflupen her, damit unsere Kunden gut sehen können.", sourceObjective = "Stellt 2 Kopflupen aus gesplittertem Onyx für Tuluradormi in Valdrakken her.", progress = "Habt Ihr die Kopflupen?", completion = "Eure Arbeit wird geschätzt... von irgendwem... bestimmt.\n\nHier, ich habe diese Steine geschliffen. Ihr könnt sie studieren, um Eure Juwelierskunst zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70565] = { id = 70565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besonderheit durch Sättigung", description = "Oh, <Juwelier/Juwelierin>, gefällt Euch meine Halskette?\n\nNatürlich tut sie das. Aber ich kann sie nicht angemessen ausstellen, wenn sie nicht heraussticht.\n\nIch hab's! Warum stellt Ihr nicht einige einfache Anhänger her, mit denen wir den Markt fluten können. Wenn erst jeder Euren Schmuck trägt, wird der funkelnde Schliff meiner Halskette alle anderen überstrahlen!", sourceObjective = "Stellt 2 Anhänger der bevorstehenden Gefahren für Tuluradormi in Valdrakken her.", progress = "Habt Ihr die Anhänger?", completion = "Alles im Namen der Mode, {name}.\n\nHier, ich habe diese Steine geschliffen. Ihr könnt sie studieren, um Eure Juwelierskunst zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70567] = { id = 70567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn man einem Bakar einen Knochen zuwirft", description = "Ich hatte so schöne knochengefertigte Bogen, aber unsere Bakar haben sie sich geschnappt, bevor sie jemand nutzen konnte. Bakar kauen nun einmal gern auf Knochen herum, Bogen hin oder her. Jetzt sind sie ruiniert!\n\nKönnt Ihr mir dabei helfen, Ersatz anzufertigen?", sourceObjective = "Stellt 2 knochengefertigte Armbrüste für Balgformer Koruz in Valdrakken her.", progress = "Wenn ich das nächste Mal so etwas bei mir trage, halte ich die Bakar auf Distanz.", completion = "Vielen Dank, {name}.\n\nHier, nehmt diese Entwürfe. Ihr könnt sie studieren, um Eure Fertigkeiten in der Lederverarbeitung zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70568] = { id = 70568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Schuppen aufgewogen", description = "Unsere Schuppenarmschienen sind meisterhaft gefertigt und werden stark nachgefragt. Ich komme bei den ganzen Bestellungen nicht mehr nach! Würdet Ihr mir mit Euren Fähigkeiten helfen, meinen Vorrat aufzustocken?", sourceObjective = "Stellt 2 Schuppenarmschienen des Wegbereiters für Balgformer Koruz in Valdrakken her.", progress = "Unsere Waren sind von höchster Qualität und meisterhaft gefertigt. Es überrascht mich nicht, dass sie sich so schnell verkaufen.", completion = "Gut gemacht, {name}.\n\nHier, nehmt diese Entwürfe als Dank für Eure Hilfe. Ihr könnt sie studieren, um Eure Fertigkeiten in der Lederverarbeitung zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70569] = { id = 70569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Korb für Trorb", sourceObjective = "Stellt 2 Blumenkörbe des Kräuterkundigen für Balgformer Koruz in Valdrakken her.", progress = "Ich denke, mit diesen robusten Körben wird Trorb viel zufriedener sein.", completion = "Vielen Dank für Eure Hilfe, {name}.\n\nHier, nehmt diese Muster. Ihr könnt sie studieren, um Eure Fertigkeiten in der Lederverarbeitung zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70571] = { id = 70571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trommelwirbel!", description = "Unsere Trommeln sind weit und breit bekannt. Die Zentauren haben sich diese Fähigkeiten über Generationen erarbeitet. Das heißt aber leider, dass unsere Trommeln derzeit Mangelware sind.\n\nWie ich sehe, könnt Ihr durchaus auch etwas. Mögt Ihr mir vielleicht helfen, einige Trommeln für unsere Lager herzustellen?", sourceObjective = "Stellt 2 Wildbalgtrommeln für Balgformer Koruz in Valdrakken her.", progress = "Eure Fähigkeiten sind beeindruckend - wo habt Ihr Eure Kunst gelernt?", completion = "Ohn'ahra segne Euch, {name}.\n\nHier, nehmt diese Muster. Ihr könnt sie studieren, um Eure Fertigkeiten in der Lederverarbeitung zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70572] = { id = 70572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kälte macht ihnen doch was aus", sourceObjective = "Stellt 2 Stoffroben des Inspektors für Fulafong in Valdrakken her.", progress = "Habt Ihr die Roben?", completion = "Vielen Dank, {name}.\n\nNehmt diese Muster, um zu lernen. Ihr könnt sie studieren, um Eure Schneiderei zu verbessern.\n\nUnd haltet Euch warm.", sourceObjectiveStatus = "unverified-source-field" }
quests[70582] = { id = 70582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alleine besser weben", sourceObjective = "Stellt 3 Wildstoffballen für Fulafong in Valdrakken her.", progress = "Habt Ihr die Ballen?", completion = "Ihr habt Euch selbst übertroffen, {name}.\n\nNehmt diese Muster, um zu lernen. Ihr könnt sie studieren, um Eure Schneiderei zu verbessern.\n\nUnd bleibt in Form.", sourceObjectiveStatus = "unverified-source-field" }
quests[70586] = { id = 70586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu viele Köche", sourceObjective = "Stellt 2 Wildstoffkochmützen für Fulafong in Valdrakken her.", progress = "Habt Ihr die Kochmützen?", completion = "Vielen Dank, {name}. Ihr hungert wohl stets nach neuen Herausforderungen.\n\nNehmt diese Muster, um zu lernen. Ihr könnt sie studieren, um Eure Schneiderei zu verbessern.\n\nUnd bleibt hungrig.", sourceObjectiveStatus = "unverified-source-field" }
quests[70587] = { id = 70587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Rucksackproblem", sourceObjective = "Stellt 1 einfach genähte Reagenzientaschen für Fulafong in Valdrakken her.", progress = "Habt Ihr die Taschen?", completion = "Vielen Dank, {name}. Das sollte reichen.\n\nNehmt diese Muster, um zu lernen. Ihr könnt sie studieren, um Eure Schneiderei zu verbessern.\n\nUnd haltet Euch von jedem fern, der Euch unendlichen Stauraum verspricht. Ihr wollt nicht wissen, was Euch am Ende dieses Weges erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[70589] = { id = 70589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedekünste sind gefragt", sourceObjective = "Erfüllt Schmiedekunstaufträge für das Handwerkerkonsortium.", completion = "Habt Dank für das Geschäft! Nur immer weiter, weiter, weiter so!", sourceObjectiveStatus = "unverified-source-field" }
