quests[70613] = { id = 70613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt eine Runde Rinde aus", sourceObjective = "Sammelt 8 Krümmrinde für Agrikus in Valdrakken.", progress = "Habt Ihr schon genug Krümmrinde gefunden?", completion = "Vielen Dank, {name}.\n\nBitte, nehmt meine Feldnotizen. Ihr könnt sie studieren, um Eure Kräuterkunde zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70614] = { id = 70614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blasenwahnsinn", description = "<Agrikus schreit Euch an.>Ich habe keinen Mohntee mehr!\n\n...Oh, Ihr seid keiner von denen. Den Titanen sei Dank. Irgendjemand hat entschieden, dass \"Blasenmohntee\" diese Woche das angesagteste Getränk ist, und das Kraut ist bei mir völlig ausverkauft. Bitte, könntet Ihr mehr Mohn sammeln, bevor sie wieder in Scharen zurückkommen?", sourceObjective = "Sammelt 8 Blasenmohn für Agrikus in Valdrakken.", progress = "<Agrikus versucht, sich zu beruhigen.>", completion = "Vielen Dank, {name}, ich danke Euch.\n\nBitte, nehmt meine Feldnotizen. Ihr könnt sie studieren, um Eure Kräuterkunde zu verbessern.\n\nIch muss... Tee kochen...", sourceObjectiveStatus = "unverified-source-field" }
quests[70615] = { id = 70615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall der vermissten Kräuter", sourceObjective = "Sammelt 8 Steinbrich für Agrikus in Valdrakken.", progress = "Habt Ihr meine Kräuter gefunden?", completion = "Vielen Dank, {name}. Was für eine Woche...\n\nBitte, nehmt meine Feldnotizen. Ihr könnt sie studieren, um Eure Kräuterkunde zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[70616] = { id = 70616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie viele?!", description = "<Agrikus weint, als Ihr Euch nähert.>\n\nSie haben es getan... Ich kann nicht fassen, dass sie es wirklich getan haben...\n\nJemand kam her und hat eine Lieferung von EINTAUSEND Kräutern verlangt!\n\nDas übersteigt meinen Verstand! Das ist absurd. Lächerlich! Irrsinnig!!\n\n...Hilfe, bitte.", sourceObjective = "Sammelt 20 Hochblumen für Agrikus in Valdrakken.", progress = "Fünfhunderteinundsechzig... Fünfhundertzweiundsechzig...\n\n<Agrikus bricht erneut in Tränen aus.>", completion = "Oh, gut. Das wird helfen. Vielen Dank für Eure Unterstützung.\n\nBitte, nehmt meine Feldnotizen. Ihr könnt sie studieren, um Eure Kräuterkunde zu verbessern.\n\nIch muss Kräuter zählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70617] = { id = 70617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles meins, meins, meins", description = "Nichts ist so nützlich wie Drakoniumerz. Man kann so viel damit machen! Es ist einfach das perfekte Erz, in jeder Hinsicht rein.\n\nBringt mir Drakonium. Ich muss es haben. Ihr seid doch <Bergarbeiter/Bergarbeiterin>, oder? Dann an die Arbeit!", sourceObjective = "Sammelt 7 Drakoniumerz für Sekita den Wühler in Valdrakken.", progress = "Nun? Habt Ihr mir mein Erz gebracht?", completion = "Ja, ja, ja! Genau das habe ich gebraucht.\n\nNehmt meine Feldnotizen mit, wenn Ihr geht. Ich habe einiges an nützlichen Informationen zum Bergbau hier auf den Inseln notiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[70618] = { id = 70618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Schmiede", description = "Die Schmiede... sie ruft nach mir. Und sie bittet um Serevit. Ihr da! Bringt mir Serevit! Ja, Unmengen an Serevit! <Sekita lacht manisch.>", sourceObjective = "Sammelt 16 Sereviterz für Sekita den Wühler in Valdrakken.", progress = "Mehr, mehr, mehr für die Schmiede!\n\n<Sekita lacht begeistert.>", completion = "Ja, ja!\n\nDas wird die Schmiede zufriedenstellen.\n\nNehmt meine Feldnotizen, bevor Ihr geht. Darin findet Ihr bestimmt etwas, das Euch mehr über Bergbau beibringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[70619] = { id = 70619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Studie zu Leder", description = "Ihr da! Vielleicht könnt Ihr mir helfen, dieses Leder zu untersuchen. Manchmal ist es weich und biegsam, andere Teile hingegen sind starrer. Letztere eignen sich wohl tendenziell besser zur Herstellung von Rüstung.\n\nBringt mir noch mehr Leder, das ich untersuchen kann. Ich würde das gerne weiter fortführen.", sourceObjective = "Sammelt 40 widerstandsfähige Leder für Ralathor den Zerfurchten in Valdrakken.", progress = "Konntet Ihr Leder für unsere Untersuchungen finden?", completion = "Vielen Dank, {name}. Damit sollte ich meine Fertigkeiten weiter schulen können.\n\nHier, nehmt meine Feldnotizen. Sie werden Euch mehr über die Wildtiere dieses Landes und darüber, wie man an ihre Häute gelangt, beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70620] = { id = 70620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Schuppen von den Augen", description = "Viele Leute fragen mich, wie ich so gut im Häuten geworden bin. Denen kann ich nur sagen: Es kommt alles von den Schuppen!\n\nWollt Ihr mehr darüber erfahren? Bringt mir Schuppen, dann zeige ich Euch, was ich meine.", sourceObjective = "Sammelt 40 Adamantschuppen für Ralathor den Zerfurchten in Valdrakken.", progress = "Habt Ihr geeignete Schuppen gefunden?", completion = "Hervorragend. Nachdem Ihr nun fleißig geübt habt, könnt Ihr besser Tiere häuten! Seht Ihr? Es kommt alles von den Schuppen.\n\nHier, nehmt meine Feldnotizen. Sie werden Euch mehr über die Wildtiere dieses Landes und darüber, wie man ihre Häute beschafft, beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70621] = { id = 70621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dritte Herausforderung von Tyr: Verkörperte Beharrlichkeit", description = "In Eurer dritten Herausforderung solltet Ihr auch unter widrigen Umständen bestehen. Sie sollte mir Euer Durchhaltevermögen in allen Dingen zeigen.\n\nIch glaube, dass Ihr die Djaradin bekämpft und meine Statue repariert habt, obwohl Ihr damit rechnen musstet, dass Ich Euch eine weitere Herausforderung stelle, sollte als erfüllte Siegesbedingung genügen.\n\n<Ihr glaubt, Ihr erkennt ein flüchtiges Lächeln auf ihren Lippen.>", sourceObjective = "Nehmt die abgefüllte Essenz von der Maid der Inspiration an.", completion = "In Eurer dritten Herausforderung solltet Ihr auch unter widrigen Umständen bestehen. Sie sollte mir Euer Durchhaltevermögen in allen Dingen zeigen.\n\nIch glaube, dass Ihr die Djaradin bekämpft und meine Statue repariert habt, obwohl Ihr damit rechnen musstet, dass Ich Euch eine weitere Herausforderung stelle, sollte als erfüllte Siegesbedingung genügen.\n\n<Ihr glaubt, Ihr erkennt ein flüchtiges Lächeln auf ihren Lippen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[70622] = { id = 70622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Vorräte für den Dreifällerundblick" }
quests[70623] = { id = 70623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saubere Luft" }
quests[70625] = { id = 70625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaubergeschmiedete Schöpfungen" }
quests[70627] = { id = 70627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist mit dem Winterpelzklan?", description = "Wir könnten einem anderen Klan beitreten... wenn wir wüssten, dass es sicher ist.\n\nIch befürchte, dass die Primalisten auch andere Klans so wie unseren in Versuchung gebracht haben.\n\nLaut dieser \"Drachenschuppenexpedition\" haben sie eine Klauenfeste nahe des Winterpelzklans.\n\nVielleicht sind sie auch schon verdorben. Oder sie hören unsere Warnung an. So oder so, sie brauchen uns.\n\nIn Therons Wacht gibt es einen \"Furbolgexperten\", Sonova Schneeweh. Bitte sucht ihn auf und bringt in Erfahrung, was er weiß.", sourceObjective = "Trefft Sonova Schneeweh bei Therons Wacht.", completion = "Bedauerlicherweise... habe ich schlechte Neuigkeiten, was die Winterpelzfurbolgs angeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[70629] = { id = 70629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Küste" }
quests[70631] = { id = 70631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saubere Luft" }
quests[70632] = { id = 70632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katalogisieren der Küste des Erwachens" }
quests[70633] = { id = 70633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maschine auf Touren bringen", description = "Ihr habt gute Arbeite geleistet und die erste Herausforderung bestanden, die Hüter Tyr hinterlassen hat. Obwohl es nur der erste Schritt auf Eurer Reise ist, glaube ich daran, dass Ihr Euch gut schlagen werdet. Ihr habt Euch die Gelegenheit verdient, die Geheimnisse der Schmiede aufzudecken.\n\nGebt die abgefüllte Essenz in die Innovationsmaschine, und wartet ab, was passiert.", sourceObjective = "Benutzt die abgefüllte Essenz, um die Innovationsmaschine mit Energie zu versorgen.", progress = "<Die Maschine summt leise, als Ihr Euch nähert.>", completion = "Ein Funke der Genialität. Dieser Gegenstand kann ein Potenzial erwecken, wie es seit der Zeit Tyrs nicht dagewesen war.\n\nIch bin sicher, Ihr werdet ihn weise nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[70634] = { id = 70634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgepeitscht" }
quests[70636] = { id = 70636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Protodrachen" }
quests[70638] = { id = 70638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windbrecher" }
quests[70639] = { id = 70639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azurbanner" }
quests[70640] = { id = 70640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Boss", description = "<Die Schrift der Seite leuchtet in einem sanften blauen Licht.>\n\nDer Elementar Frigellus, einst ein geliebtes Spielzeug von Malygos, litt unter der Vernachlässigung durch seinen Herrn.\n\nWährend dieses einst glückliche Dorf immer weiter zerfiel, wurde das neckische und verspielte Wesen von den Übeln, die dieses Land plagen, entstellt und verdreht.\n\nBitte neutralisiert dieses Wesen.\n\nTeilt Euren Erfolg anschließend dem Hüter Cynegos mit.", sourceObjective = "Tötet Frigellus in der Nähe von Lager Antonidas.", sourceObjectiveStatus = "unverified-source-field" }
quests[70641] = { id = 70641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein augenöffnender Schwur", sourceObjective = "Sprecht mit Mitgliedern des roten Drachenschwarms am Rubinlebensschrein.", progress = "Die {race} haben noch viel über die Schwärme zu lernen, {name}.", completion = "Uns allen sind Geschichten des Wachstums gemein. Ich hoffe, Ihr könnt nun besser nachvollziehen, wo unsere Wurzeln liegen und wohin wir streben.", sourceObjectiveStatus = "unverified-source-field" }
quests[70643] = { id = 70643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkaner Sprengstoff" }
quests[70644] = { id = 70644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Wildziege" }
quests[70646] = { id = 70646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druckventil" }
quests[70647] = { id = 70647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo nur, wo könnte er bloß sein?", description = "{name}, Ich bin so froh, Euch zu sehen! Ich bin ganz krank vor Sorge und könnte Eure Hilfe brauchen.\n\nIch habe vor Kurzem einen verlassenen Protodrachenwelpen gerettet und Lubbins getauft, weil er so liebenswert ist! Ich habe ihn hierhergebracht, um mich um ihn zu kümmern und vielleicht ein gutes Zuhause als Haustier für ihn zu finden.\n\nAber jetzt ist er verschwunden und ich habe Angst, dass er sich verirrt hat oder gar verletzt ist. Ich muss mich um die anderen Kleinen hier kümmern, sonst würde ich ihn ja selbst suchen gehen. Wärt Ihr wohl so gut, nach ihm zu suchen?", sourceObjective = "Rettet Lubbins und bringt ihn zu Jyhanna bei der Krippe \"Kleinschuppe\" in Valdrakken zurück.", completion = "Vielen Dank, {name}. Ich bin so froh, den kleinen Lubbins gesund und munter zu sehen.\n\nOh, er scheint Euch zu mögen!", sourceObjectiveStatus = "unverified-source-field" }
quests[70648] = { id = 70648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firava der Entzünder" }
quests[70649] = { id = 70649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flunkerabstrich" }
quests[70650] = { id = 70650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrs Fußspuren: Die Küste des Erwachens", description = "Ihr habt Euch bisher gut geschlagen. Und obwohl ich großes Vertrauen habe, dass Ihr der Maschine würdig seid, muss ich Euch herausfordern, wie es meine Bestimmung ist. \n\nGeht an die Küste des Erwachens und findet meine Statue. Dort werdet Ihr weitere Anweisungen erhalten.", sourceObjective = "Findet die dritte Herausforderung von Tyr an der Küste des Erwachens.", completion = "<Die einst majestätische und eindrucksvolle Statue liegt in Trümmern.>", sourceObjectiveStatus = "unverified-source-field" }
